-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[1] = { id = 1, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanrethad's Quest", description = "Welcome back from the world of death. \n\nIn an age long past you stood proud, a hero among your brethren. Now you stand fallen and broken - a relic of the past. Stand before me, as I awaken the legend that you once were. \n\n I shall restore the weapons and powers you have lost, making you whole once again.", objectives = "Speak to Kanrethad to restore your talents, weapon and mount.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2] = { id = 2, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharptalon's Claw", description = "The mighty hippogryph Sharptalon has been slain, with the claw of the felled beast serving as a testament to your victory.\n\nSenani Thunderheart at the Silverwind Refuge will no doubt be interested in seeing this trophy as proof of your deeds.", progress = "What have you there, {class}? Could it be....?", completion = "You have slain the beast?\n\nI owe you a great debt, friend. That beast terrorized many over the years, but its death holds special meaning to me.\n\nYou see, recently my brother fell victim to these very claws... I shall sleep well now, knowing that he has been avenged.", objectives = "Bring Sharptalon's Claw to Senani Thunderheart at Silverwind Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5] = { id = 5, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jitters' Growling Gut", description = "I've been stuck hiding in this ghost town for weeks, and I haven't eaten anything but grubs and weeds!  I need some decent food, and I'm willing to trade well for it.\n\nBring me a feast and I'll pay you handsomely.\n\nI heard Chef Grual at the Scarlet Raven Tavern in Darkshire makes very good Dusky Crab Cakes...", completion = "You need some Crab Cakes, do you?  Well I might be able to cook some up for you...", objectives = "Speak with Chef Grual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[6] = { id = 6, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty on Garrick Padfoot", description = "Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge.  Bring me the villain's head, and earn his bounty!\n\nBut be wary, {name}.  Garrick has gathered a gang of thugs around him.  He will not be an easy man to reach.", progress = "Did you find Garrick's shack?  Are we finally free of that villain?", completion = "Hah - you caught him!  You've done Elwynn a great service, and earned a nice bounty!", objectives = "Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[7] = { id = 7, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobold Camp Cleanup", description = "Your first task is one of cleansing, {name}.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.", completion = "Well done, citizen.  Those kobolds are thieves and cowards, but in large numbers they pose a threat to us.  And the humans of Stormwind do not need another threat.\n\nFor defeating them, you have my gratitude.", objectives = "Kill 6 Kobold Vermin, then return to Marshal McBride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8] = { id = 8, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rogue's Deal", description = "Hey, mate! Do a favor for a young man who's been fighting more than his fair share of mindless zombies and spiders?\n\nI got this here letter that needs to go to Brill... to an innkeeper named Renee something-or-other. Don't really matter none what her last name is.\n\nAnyway, it's a nice cozy little place full of victims of the plague trying to make their way in the world. And it be a great spot for you to rest too if the need arises. You should check it out... you do and I'll pay you well.", progress = "Yes? Yes? What is it?\n\nThe forsaken; they certainly do have huge appetites. Make yourself at home... yes, rest those weary bones. My name's Renee if you need anything at all.", completion = "Oh? A letter? Wonderful news! I've been waiting on word from my dear old mother in Deathknell. Such a saint, she is. I wonder how she's holding up.\n\nWhat? Too cheery? Not buying it, are you?\n\nWell, get lost then... it's really no business who the letter's from anyway. Go on! Get lost!\n\nCome back when you've got some coin to spend... loafer.\n\nNext thing you know, you'll be coming back to rest after a long days adventure or some stupid thing like that.", objectives = "Deliver the Nondescript Letter to Innkeeper Renee in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9] = { id = 9, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Killing Fields", description = "Look at what has happened to this place!  These lands were once occupied by good farm folk.  But the damned thieves have driven them all off.  Not me, though!  But it seems some Harvest Watchers have taken over the fields.\n\nIf you're up for the work, I'd like you to go out and kill twenty of them.  Come back when you're done for your pay.  If you finish up with the ones in my field, clear them from the neighboring fields as well.", completion = "Good work, friend.  You have earned your pay well.  Who knows, perhaps Westfall will prosper once again.", objectives = "Farmer Saldean wants you to kill 20 Harvest Watchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10] = { id = 10, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scrimshank Redemption", description = "Oh, this is just terrible!  I sent out my top assistant, Junior Surveyor Scrimshank, into the desert southeast of here.  That's an area we call the Gaping Chasm.  Well, he's gone missing, and his last report had more of those weird bugs where he was.  Could it be that they've infested two major regions of the desert now?\n\nI need you to head into the Gaping Chasm and look for Scrimshank, please!  That... or at least find his surveying equipment.  I fear that may be all that is left of the poor sod.", progress = "Well, what news do you have?  You look like you've been in quite the fight... is Scrimshank alive?", completion = "He was a good goblin, young Scrimshank.  Let's hope that his demise was not in vain by what he was able to record with his surveying equipment.\n\nIt seems as though we have quite the situation on our hands here with these bugs.  They're way too cunning for their own good, and the research we've done so far is shaping up to indicate that they might even be under the controlling influence of a third party!  If this is the case, then it bodes ill for not only Gadgetzan, but the whole desert!", objectives = "Discover the fate of Junior Surveyor Scrimshank, and bring either him or his surveying equipment to Senior Surveyor Fizzledowser in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11] = { id = 11, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverpaw Gnoll Bounty", description = "Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest.  A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder.  Another group has infested the areas near Stone Cairn Lake to the east.\n\nThe Stormwind Army will commend whomever helps kill them.  Bring me their painted gnoll armbands as proof of your deed.", progress = "Hail, {name}.  Have you been killing Gnolls...?", completion = "I see you've been busy!  You have our thanks, {name}.", objectives = "Bring 8 Painted Gnoll Armbands to Deputy Rainer at the Barracks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12] = { id = 12, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The People's Militia", description = "The People's Militia has but one goal:  To defend the lands of Westfall and return peace to our surroundings.  Unfortunately, the price of peace is often blood. \n\nOne of my scouts has brought word of a band of Defias Trappers wreaking havoc nearby.  I have reports of Defias Trapper sightings near the Jangolode Mine to the Northwest as well as at the Molsen Farm and Furlbrow's Pumpkin Farm. If you seek to join our ranks, slay 15 Defias Trappers and 15 Defias Smugglers then return to me.", completion = "Well done, {name}.  My scout witnessed your valiant acts.  You are proving yourself quite well so far.", objectives = "Gryan Stoutmantle wants you to kill 15 Defias Trappers and 15 Defias Smugglers then return to him on Sentinel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13] = { id = 13, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The People's Militia", description = "A band of vicious Defias Pillagers has been seen plundering the Gold Coast Quarry, Moonbrook and the Alexston Farmstead.  The People's Militia will not stand for such behavior.  Dispatch immediately, {name}, and make the Light's presence known in Westfall.\n\nThe Gold Coast Quarry is near the shore, to the West of the tower.  As the next step of your training, I want you to kill 15 of those foul Defias Pillagers and 15 Defias Looters.", completion = "Your worth to The People's Militia has been validated by your brave acts thus far.", objectives = "Gryan Stoutmantle wants you to kill 15 Defias Pillagers and 15 Defias Looters and return to him on Sentinel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14] = { id = 14, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The People's Militia", description = "Some Defias have eluded us.  My most trusted scout reports that these Defias have been looting and pillaging the countryside, all the way into Southern Westfall.  We believe they are hiding out in the Dagger Hills, plotting their next move.   Slay the wretches in the name of The People's Militia.", completion = "When I left the tainted lands of Lordaeron I returned to a grim state of affairs here in my homeland.  But there is hope for Westfall yet.  As proven by your valor in battle, it is obvious to me that you serve our cause with honor.  It is with great pride that I induct thee into The People's Militia.  May the Light shine upon you.", objectives = "Gryan Stoutmantle wants you to kill 15 Defias Highwaymen, 5 Defias Pathstalkers and 5 Defias Knuckledusters then return to him on Sentinel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[15] = { id = 15, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate Echo Ridge", description = "{name}, my scouts tell me that the kobold infestation is larger than we had thought.  A group of kobold workers has camped near the Echo Ridge Mine to the north.\n\nGo to the mine and remove them.  We know there are at least 8.  Kill them, see if there are more, then report back to me.", completion = "I don't like hearing of all these kobolds in our mine.  No good can come of this.  Here, take this as payment, and when you're ready, speak to me again.  I would like you to go back to the mines one more time...", objectives = "Kill 8 Kobold Workers, then report back to Marshal McBride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[16] = { id = 16, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Gerard a Drink", progress = "Farming is thirsty work, and I'm always looking for refreshing spring water.\n\nIf you have any, then I'm willing to make a trade.", completion = "Thanks, {name}!  And come back if you want to trade again." }
quests[17] = { id = 17, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uldaman Reagent Run", description = "I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters at the Uldaman dig site and can be found in the early tunnels and deep within the less-explored areas.  I want to study their potential use in alchemy, and that's where you come in.\n\nFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.\n\nDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!", progress = "Have you obtained the magenta fungus caps I need for my alchemical work?  No caps - no reward!", completion = "Well done {name}, you've proven your worth once again!  The caps will be an interesting study, yon verily!\n\nAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...\n\nIf you are a skilled alchemist, then perhaps we might have some additional business to conduct.  Regardless, I thank you for your assistance!", objectives = "Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[18] = { id = 18, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brotherhood of Thieves", description = "Recently, a new group of thieves has been hanging around Northshire.  They call themselves the Defias Brotherhood, and have been seen across the river to the east.\n\nI don't know what they're up to, but I'm sure it's not good!  Bring me the bandanas they wear, and I'll reward you with a weapon.", progress = "Have you gathered those bandanas for me yet?", completion = "Back with some bandanas, I see.  The Stormwind Army appreciates your help.", objectives = "Bring 8 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[19] = { id = 19, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tharil'zun", description = "Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep.  The leader of the Outrunners is an orc named Tharil'zun--we want this orc.  Bring me the head of Tharil'zun!", progress = "Orc pressure from Blackrock is still tense.  But have you at least rid us of Tharil'zun?", completion = "Tharil'zun was a vicious, crafty orc.  Well done--I'm sure he didn't go down easy.  Here is your reward, {name}.", objectives = "Bring Tharil'zun's Head to Marshal Marris in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[20] = { id = 20, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Menace", description = "The Blackrock orcs have travelled from the Burning Steppes and claimed Stonewatch Keep to the north.  From there they maraud the areas north of Lakeshire and keep its citizens in town, penned like cattle.\n\nHelp rid Lakeshire of this menace.  Kill these Blackrock orcs and bring me ten of their Battleworn Axes as proof.\n\nAnd although Blackrocks threaten us from the north, we've received reports of more in the southeastern pocket of Redridge.  If you find any there, then they too should be hunted.", progress = "Have you been slaying orcs, {name}?  If so, then show me...", completion = "That makes for a lot fewer orcs to worry about, thanks.", objectives = "Bring 10 Battleworn Axes to Marshal Marris in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[21] = { id = 21, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skirmish at Echo Ridge", description = "Your previous investigations are proof that the Echo Ridge Mine needs purging.  Return to the mine and help clear it of kobolds.\n\nWaste no time, {name}.  The longer the kobolds are left unmolested in the mine, the deeper a foothold they gain in Northshire.", completion = "Once again, you have earned my respect, and the gratitude of the Stormwind Army.  There may yet be kobolds in the mine, but I will marshal others against them.  We have further tasks for you.", objectives = "Kill 8 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[22] = { id = 22, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goretusk Liver Pie", description = "The onions are peeled.  The garlic is minced.  The rosemary is crushed.  The crust has been baked.  The dill weed is chopped.  The gravy is simmering.  Now all I need for my famous meat pie are 8 Goretusk Livers!", progress = "All I need for my famous meat pie are 8 Goretusk Livers!", completion = "These are just perfect, {name}!  Thank you so much.  Farmer Saldean and I are going to feast tonight.  And here is a little something for you, for the hard work.  You didn't think I was going to let a {class} like you go hungry, did you?", objectives = "Salma Saldean needs 8 Goretusk livers to make a Goretusk Liver Pie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[23] = { id = 23, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursangous' Paw", description = "The mighty bear Ursangous is no more!\n\nThe small quarter-crescent emblem on its paw indicates that this beast was trained by the night elves to prowl the forest in search of their enemies. There is no telling how many of your Horde allies fell to this creature.\n\nThe paw should be brought to Tarkan at Silverwind Refuge. He will be pleased that such a weapon has been removed from the enemy's arsenal.", progress = "What is it, {race}?", completion = "The paw of Ursangous!\n\nHave you any idea what trouble this beast has caused us over the years? Those days are over now, thanks to you.\n\nI shall forward this trophy on to Orgrimmar to be put on display, along with your account of its death.\n\nCongratulations!", objectives = "Bring Ursangous' Paw to Captain Tarkan at Silverwind Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24] = { id = 24, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadumbra's Head", description = "The once swift Shadumbra now lies still as you claim victory over it.\n\nThis legenday creature is dear to the night elves. Its head should serve as an intimidating trophy, and as a sign of the end of the Alliance in Ashenvale.\n\nCaptain Goggath at Hellscream's Watch will no doubt be delighted to receive the head of the slain nightsaber.", progress = "Yes, {class}?", completion = "Shadumbra's Head?\n\nNone can say how many of our Horde brethren have fallen to this beast over the years. Your prowess has ensured that no more shall suffer this fate.\n\nWarchief Hellscream shall hear of your deeds, {class}.", objectives = "Bring Shadumbra's Head to Captain Goggath at Hellscream's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25] = { id = 25, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simmer Down Now", description = "You should've seen it, {class}!\n\nThe elves thought Silverwind to be impenetrable. With its heavy defenses and their army of water elementals, they were almost right.\n\nAlmost.\n\nOne of our mages was able to summon a twisted elemental designed to send the others into a chaotic rage.\n\nAhh, the looks on their faces!\n\n<Tarkan laughs.>\n\nUnfortunately, the mage who summoned it fell in battle. Now I need someone to bring down our creation.", completion = "Well done, {class}.\n\nA fitting end to a textbook assault.", objectives = "Captain Tarkan at Silverwind Refuge wants you to defeat Tideress and 12 Befouled Water Elementals at Mystral Lake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26] = { id = 26, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson to Learn", description = "{name}, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature.\n\nThe time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.", completion = "Salutations, young {class}; the time has come for you to know our aquatic form. It is one that lets you move freely and indefinitely through water. You will find this aspect a useful tool and a blessing... but it is one that must be earned before it is mastered.\n\nYou will face two trials to overcome. The first will test your ability to work in water under pressure. The second will test your resolve to understand the aspects of the form itself.\n\nStand ready, as the time of testing is now upon us.", objectives = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27] = { id = 27, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson to Learn", description = "{name}, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature.\n\nThe time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.", completion = "Salutations, young {class}; the time has come for you to know our aquatic form. It is one that lets you move freely and indefinitely through water. You will find this aspect a useful tool and a blessing... but it is one that must be earned before it is mastered.\n\nYou will face two trials to overcome. The first will test your ability to work in water under pressure. The second will test your resolve to understand the aspects of the form itself.\n\nStand ready, as the time of testing is now upon us.", objectives = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28] = { id = 28, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Lake", description = "For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.\n\nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.\n\nGood luck, {name}.", completion = "Well now, it looks like yet another {class} has successfully completed the Trial of the Lake! Well done, my young friend - well done.\n\nAs I've said, my name is Tajarri. It is my duty and my privilege to serve as a warden for Moonglade, and specifically this shrine. Keeper Remulos guides the Cenarion Circle in preservation of nature and balance, and his shrine serves as a lasting tribute to such. By using the bauble here, it serves as a nod to the importance of this place within the Circle.", objectives = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade. Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29] = { id = 29, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Lake", description = "For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.\n\nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.\n\nGood luck, {name}.", completion = "Well now, it looks like yet another {class} has successfully completed the Trial of the Lake! Well done, my young friend - well done.\n\nAs I've said, my name is Tajarri. It is my duty and my privilege to serve as a warden for Moonglade, and specifically this shrine. Keeper Remulos guides the Cenarion Circle in preservation of nature and balance, and his shrine serves as a lasting tribute to such. By using the bauble here, it serves as a nod to the importance of this place within the Circle.", objectives = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade. Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30] = { id = 30, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Sea Lion", description = "For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.\n\nSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.", progress = "Have you formed your pendant for me to inspect, {name}? If you need help in locating the parts, try asking the local populace for information. Not only will you find what you seek, but it will give you a reason to explore this wondrous and sacred glade.", completion = "You've completed the Trial of the Sea Lion, {name} - congratulations.\n\nEach task in acquiring the pendant shows that both agility and endurance are necessary to act in harmony with what you desire to do underwater.  Neither can exist without the other, and both cannot be done without your willingness to embrace the aspect of the sea lion.\n\nRemember these lessons well, and count on them once you have gained your aquatic form.", objectives = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance. Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves. You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31] = { id = 31, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aquatic Form", description = "You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect.  Go now back to your trainer, Turak Runetotem, in Thunder Bluff.  Show him your pendant and prove to him you are ready to learn what he has to teach you.  He will complete your training, allowing you to become one with the water.\n\nGoodbye, young druid.  We shall speak again.", objectives = "Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32] = { id = 32, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise of the Silithid", description = "Here's your report.  I urge you to take it to someone who might have working knowledge in this kind of thing.\n\nI know this troll scholar named Zilzibin Drumlore.  He's spent a lot of time studying life forms that are unique to the ecology of Azeroth; he's a historian to boot!  If you want someone to help figure out what exactly this threat is and how to stop it, give this report to him.  We're going to need all the help we can get.\n\nZil lives in a house on the second tier of the Drag in Orgrimmar.", progress = "I'm sorry, I don't know you... but from the look of things you have at least heard something of me.  Now, what can I help you with?  Do you have something for me?", completion = "This report... I've dealt with these beasts before.  Fizzledowser was wise to send this, and you, to me.\n\nThese creatures will consume the Tanaris desert rapidly; they are nothing short of one of the greatest menaces we all will ever face.  Familiarize yourself with this name, {name}: silithid.  The insects mentioned here are the silithid, and they are the tools of one of the greatest threats that both the Horde and Alliance face.\n\nIf only we were smart enough to see that before.", objectives = "Take the report to Zilzibin Drumlore in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33] = { id = 33, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolves Across the Border", description = "Whatever is affecting these wolves isn't going away. Each day that passes brings forth more sick wolves. It pains me to ask anyone to kill nature's beasts, but we must destroy the diseased young wolves before this little outbreak turns into an epidemic.\n\nKill diseased young wolves in the valley and bring me their diseased wolf pelts as proof of your deed.", progress = "Hey {name}. How goes the hunt for diseased young wolves?", completion = "'Twas a grim task, friend, but you held up your part of the bargain.\n\nI have some things here you might want - take your pick!", objectives = "Bring 8 Diseased Wolf Pelts to Eagan Peltskinner outside Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34] = { id = 34, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Guest", description = "Once again my garden was trampled and pillaged.  And I know the brute who is doing it.  It's that forsaken boar, the one Marshal Marris has taken to calling Bellygrub.\n\nI won't be able to re-plant the daffodils until next season now.  Ruined!  All ruined by that one menacing boar.  Put an end to that pest!  Show me his tusk and I'd be happy to reward you.  He seems to spend his time foraging in the field southwest of Lakeshire but occasionally he roams over here and into my garden.", progress = "Is Bellygrub still at it or were you able to rid Lakeshire of the pest once and for all?", completion = "Finally the menace is laid to rest!  Thank you, {name}, you have done me a great service.  The garden shall be in full bloom this season!", objectives = "Martie Jainrose of Lakeshire wants you to kill Bellygrub. Bring her his tusk as proof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35] = { id = 35, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Concerns", description = "If you are concerned that the rumors of murlocs are true, then do this -- travel to the eastern Elwynn bridge and speak with Guard Thomas.  He has been stationed at the bridge for the past week and will know the state of the area.\n\nI have here a Stormwind charger that will take you to Guard Thomas. Let me know if you wish to make use of the horse.", completion = "Yes, murlocs have settled in and around the streams of eastern Elwynn.  We don't know why they are here, but they are aggressive and at least semi-intelligent.", objectives = "Marshal Dughan wants you to speak with Guard Thomas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36] = { id = 36, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfall Stew", description = "I never thought the day would come when I'd leave the farm.  But the fields are overrun with thieves and it's far too dangerous for us here now.  As soon as Farmer Furlbrow gets the wagon fixed, we'll be on our way.  \n\nMaybe you could do me a favor?  Let me scribble down my recipe for Westfall stew.  Please take it to Salma Saldean over on the farm yonder.  The Saldean's farm is just beyond the fork in the road.", progress = "I'm going to miss that Verna Furlbrow so much.  I don't suppose you happened to see her on your way here?", completion = "That Verna was always such a sweet lass.  We'll miss her here in Westfall but between you and me, she's a city girl at heart and Stormwind will suit her just fine.  But enough gossip!  Now we can make Westfall Stew!", objectives = "Verna Furlbrow wants you to deliver her recipe for Westfall Stew to Salma Saldean.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37] = { id = 37, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Lost Guards", description = "A few days ago we sent two Guards, Rolf and Malakai, to investigate along the river, and they have not yet returned.  To complete my report, I must know what happened to those men.\n\nTravel north along the river and find the guards... or their remains.", completion = "Although much has been stripped from the corpse, strewn nearby is a medallion with the words: \"Footman Malakai Stone\" etched upon it.", objectives = "Guard Thomas wants you to travel north up the river and search for the two lost guards, Rolf and Malakai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38] = { id = 38, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfall Stew", description = "Help me make some Westfall Stew!  Come back with the following ingredients: \n\n 3 Stringy Vulture Meat \n 3 Goretusk Snouts \n 3 Murloc Eyes \n 3 Okra", progress = "Come back with the following ingredients: \n\n 3 Stringy Vulture Meat \n 3 Goretusk Snouts \n 3 Murloc Eyes \n 3 Okra", completion = "That Okra will thicken up this broth nicely!  Now we just add the Stringy Vulture Meat, a few Murloc Eyes and those delicious Goretusk Snouts.  And we're done!  For all your help, {name}, I want you to take today's first batch of Westfall Stew!", objectives = "Salma Saldean wants 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes, 3 Okra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39] = { id = 39, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver Thomas' Report", description = "Tell Marshal Dughan of Malakai and Rolf's deaths, and report to him that the Murlocs in eastern Elwynn cannot be contained by our current troop presence.\n\nI know we don't have many troops to spare, but hopefully Dughan can find someone.", completion = "Hmm, this news is troubling.  Already our defenses are stretched thin, and losing Rolf and Malakai to those murlocs put us in an even worse position.\n\nIf things don't improve, there will be fighting in Goldshire by the week's end!", objectives = "Report to Marshal Dughan in Goldshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40] = { id = 40, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fishy Peril", description = "{name}, there's a new threat in Elwynn Forest!  Murlocs are swimming up the streams of eastern Elwynn, scaring away fish and attacking gentle folk!\n\nI warned Marshal Dughan, but he's more worried about the gnolls and the bandits.  He's not convinced that the murlocs are a danger.\n\nPlease, {name}, speak to Dughan and persuade him to send more troops to the east!", completion = "Yes, I spoke with Remy.  I respect him as a merchant, though all reports of Murlocs to the east have been sketchy at best.\n\nYour concerns are noted, but unless I receive a military report of a murloc threat, we can't afford to send more troops east.", objectives = "Remy \"Two Times\" wants you to speak with Marshal Dughan in Goldshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45] = { id = 45, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discover Rolf's Fate", description = "Upon further searching the area, you find webbed footprints leading east along the shore of Stone Cairn Lake.  In the distance to the east, you can just barely see a Murloc village.\n\nPerhaps Rolf's fate ended there...", completion = "You find around the neck of the corpse a metal medallion inscribed with the words: \"Footman Rolf Hartford.\"", objectives = "Search the murloc village for Rolf, or signs of his death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46] = { id = 46, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty on Murlocs", description = "The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn.  Slaughter them and bring Guard Thomas their torn murloc fins, and the Stormwind Army will reward you well.\n\nThe murlocs have built a village at Stone Cairn Lake north of here, and another to the south where the stream forks.", progress = "How goes the hunting, {name}?", completion = "You have the fins?  Great!  Marshal Dughan is anxious about the Murloc situation in eastern Elwynn, and I'd like to tell him that it's becoming under control.\n\nYour actions have helped realize that.", objectives = "Bring 8 Torn Murloc Fins to Guard Thomas at the east Elwynn bridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47] = { id = 47, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gold Dust Exchange", description = "The kobolds in these parts sometimes carry Gold Dust on them.  I could really use the stuff - bring me a load of it and I'll give you the best price in town...best price in town!\n\nYou can find kobolds in the Fargodeep Mine to the south, and around the Jasperlode Mine to the northeast.", progress = "Psst!  You have that Gold Dust for me...for me?", completion = "Thanks for the dust, {name}.  Here's your cash, and...here is a token from associates of mine.  You might find it useful...useful.", objectives = "Bring 10 Gold Dust to Remy \"Two Times\" in Goldshire. Gold Dust is gathered from Kobolds in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48] = { id = 48, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet Amber", description = "In the land to the south where vines twist and creep\nLies a hidden well where the water runs deep\nPure as the Light's sacred Daughter\nBring to me now some Holy Spring Water.", progress = "Hiccup! Ho ho!  You want an encore?\n\nIn the land to the south where vines twist and creep\nLies a hidden well where the water runs deep\nPure as the Light's sacred Daughter\nBring to me now some Holy Spring Water.", completion = "Hiccup! Ho Ho!", objectives = "Bring Holy Spring Water to Grimbooze Thunderbrew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49] = { id = 49, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet Amber", description = "Amber is the hue of my life's longest love\nLike the last embers of dusk in the sky above\nRetrieve for me so that my love shall be born\nOne sack of each: barley, rye and corn.", progress = "Encore? Well, sure!\n\nAmber is the hue of my life's longest love\nLike the last embers of dusk in the sky above\nRetrieve for me so that my love shall be born\nOne sack of each: barley, rye and corn.", completion = "Hiccup! Ho ho!", objectives = "Grimbooze Thunderbrew wants a Sack of Barley, a Sack of Rye and a Sack of Corn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50] = { id = 50, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet Amber", description = "I'll mix and mix till we have a mash\nFor this will be our own private stash\nA still must be fashioned of metal strong\nBring me some Truesilver so I can finish this song.", progress = "An encore for you?  Well sure friend!\n\nI'll mix and mix till we have a mash\nFor this will be our own private stash\nA still must be fashioned of metal strong\nBring me some Truesilver so I can finish this song.", completion = "Hiccup! Ho ho!", objectives = "Grimbooze Thunderbrew wants Truesilver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51] = { id = 51, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet Amber", description = "Not yet filtered but freshly distilled\nLike unseeded land waiting there tilled.\nNext I will fashion our pile of charcoal\nDeliver a sycamore branch, that is your next goal.", progress = "An encore?  Why for you, anything!\n\nNot yet filtered but freshly distilled\nLike unseeded land waiting there tilled. \nNext I will fashion our pile of charcoal\nDeliver a sycamore branch, that is your next goal.", completion = "Hiccup! Ho ho!", objectives = "Bring a Sycamore Branch to Grimbooze Thunderbrew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52] = { id = 52, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protect the Frontier", description = "Hail, {name}.  Wild animals are growing more and more aggressive the farther we get from Goldshire, and the Eastvale Logging Camp suffers nearly constant attacks from wolves and bears!\n\nWe could use your help out here.", progress = "Have you killed those wolves and bears?", completion = "Thanks a lot for the help, {name}.  Something in the forest must be making these animals so bold.\n\nWhatever it is, I hope it stays there.", objectives = "Kill 8 Prowlers or Gray Forest Wolves and 5 Young Forest Bears, and then return to Guard Thomas at the east Elwynn bridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53] = { id = 53, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet Amber", description = "Mellifluous liquid clear as a baby's tears\nTurns a lovely deep amber over the years\nBut before we proceed to get lit to the hilt\nA barrel of charred oak must be built.", progress = "Sure, I'll sing it again for you, friend!\n\nMellifluous liquid clear as a baby's tears\nTurns a lovely deep amber over the years\nBut before we proceed to get lit to the hilt\nA barrel of charred oak must be built.", completion = "Aged in the barrel, filtered through coal\nIt passes your lips and right through your soul.\nSo lets us drink now, a toast to you\nAnd me while we're at it, Grimbooze Thunderbrew!", objectives = "Bring Grimbooze Thunderbrew a bundle of Charred Oak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54] = { id = 54, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Goldshire", description = "{name}, you are a {class} with proven interest in the security of Northshire. You are now tasked with the protection of the surrounding Elwynn Forest.\n\nIf you accept this duty, then I have prepared papers that must be delivered to Marshal Dughan in Goldshire. Goldshire lies along the southern road, past the border gates.", progress = "You have word from McBride?  Northshire is a garden compared to Elwynn Forest, but I wonder what Marshal McBride has to report.\n\nHere, let me have his papers...", completion = "Well, it says here that you've been awarded Acting Deputy Status with the Stormwind Marshals.  Congratulations.\n\nAnd good luck - keeping Elwynn safe is no picnic... what with most the army busy doing who knows what for who knows which noble!\n\nIt's hard to keep track of politics in these dark days...", objectives = "Take Marshal McBride's Documents to Marshal Dughan at Goldshire in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55] = { id = 55, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morbent Fel", description = "Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery.  His time in this land is drawing to an end...\n\nUse Morbent's Bane against him.  It will render his protective magics powerless.\n\nSlay him.  Slay him, and save us from his wickedness.  Be the instrument of my revenge, and a hero of Duskwood!", progress = "Is Morbent Fel defeated?!", completion = "Morbent Fel has been defeated.  The dark riders are still at large, but a small piece of that which I had hoped beyond hope has come to pass.\n\nYou have done the impossible, and your deeds will forever live in the legends of Duskwood.\n\nGo, {name}.  And perhaps, one day, fate may bring you back to me...", objectives = "Use Morbent's Bane on Morbent Fel, kill Morbent Fel, then return Morbent's Bane to Sven at his camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56] = { id = 56, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Night Watch", description = "As Commander of The Night Watch it is my sworn duty to protect the citizens of Darkshire.  Stormwind has retracted their commissioned guards from their posts here, leaving us to our own devices.\n\nIf you feel worthy of the task, we need your help! Assist The Night Watch by venturing forth into Tranquil Gardens, just south of Darkshire, and slaying 8 Skeletal Warriors and 6 Skeletal Mages.  The undead threat must be thwarted!", completion = "Splendid, {name}.  For your service to the people of Darkshire you shall be rewarded.", objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 8 Skeletal Warriors and 6 Skeletal Mages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57] = { id = 57, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Night Watch", description = "{name}, I'm getting reports of an undead infestation in the forest!  If you're up to the job, journey to the Raven Hill graveyard and slay 15 of those vile Skeletal Fiends and 15 Skeletal Horrors.  There are also reports of skeletons just south of Darkshire, in and around Tranquil Gardens Cemetery.  The undead must be driven from Duskwood!", completion = "The people of Darkshire thank you, {name}.  You have proven yourself to be a great ally of The Night Watch.", objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 15 Skeletal Fiends and 15 Skeletal Horrors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58] = { id = 58, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Night Watch", description = "The situation in Raven Hill is still grim.  The safety of Darkshire is in your hands, {name}.  I don't have enough Watchers to keep the town safe.  We need you to dispatch for Raven Hill yet again and rid the eastern mausoleum of 20 Plague Spreaders!", completion = "On behalf of the people of Darkshire and as the Leader of the Night Watch, I thank you, {name}, for your bravery and dedication.  May the Light shine upon your ways.", objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 20 Plague Spreaders in the eastern Raven Hill mausoleum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59] = { id = 59, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth and Leather Armor", description = "For your shrewdness and valor, I have a marker here that is good for one piece of armor.  I want you to take it to Sara Timberlain at the Eastvale Logging Camp.  Give her the marker, and she will fashion the armor for you.  And after you receive it, {name}, use it in the defense of Elwynn.\n\nEastvale is just east of this post across the bridge.", progress = "I have been commissioned by the Stormwind Army to supply their people with cloth and leather armor.\n\nIf you have a marker for me, then I'd be happy to make you something.", completion = "Ah, thank you for the marker.  Please feel free to pick your choice of armor.\n\nLuck to you, brave {class}.  And may this armor serve you well.", objectives = "Give Sara Timberlain the Stormwind Armor Marker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60] = { id = 60, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobold Candles", description = "Hello, <good sir/my lady>!  Do you have a moment?\n\nMy brother and I run an apothecary in Stormwind, and I'm here to gather large candles for their wax.  Can you help me?\n\nYou can get large candles from kobolds, and I hear rumors that kobolds are infesting the Elwynn mines... the Fargodeep Mine to the south and Jasperlode Mine to the east.  I suggest looking for candles in one of those places.", progress = "Did you gather those candles yet?", completion = "You were busy hunting kobolds, were you?  Thanks for the candles, {name}, and here's your reward...", objectives = "Bring 8 Large Candles to William Pestle in Goldshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61] = { id = 61, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipment to Stormwind", description = "My brother Morgan is waiting in Stormwind for my shipment of candles.  I don't have enough time to make the trip myself, but if you'd like to take him the shipment, he'll pay you well.\n\nI've packed up the candles, and you can find Morgan in our shop, Pestle's Apothecary, in the Stormwind Trade District.", progress = "Oh, a shipment from my brother?  Splendid!  Fortune truly shines on me today!", completion = "Here is your payment ... and while you're here, take a look around!  I'm sure we have a potion or other trinket you'd find useful.", objectives = "Bring William's Shipment to Morgan Pestle in the Stormwind Trade District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62] = { id = 62, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fargodeep Mine", description = "The mine in Northshire isn't the only one with problems!  I have reports that the Fargodeep Mine in Elwynn has also become a haven for Kobolds.\n\nExplore the mine and confirm these reports, then return to me.  The mine is almost due south of Goldshire, between the Stonefield and Maclure homesteads.", completion = "This is bad news.  What's next, dragons?!?  We'll have to increase our patrols near that mine.  Thanks for your efforts, {name}.  And hold a moment... I might have another task for you.", objectives = "Explore the Fargodeep Mine, then return to Marshal Dughan in Goldshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63] = { id = 63, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Along the coast of Silverpine, west of the Sepulcher, you will find a shrine that has become tainted by the plague. The spirits there no longer speak to our people and it will be up to you to defeat the manifestation and cleanse the pool.\n\nTake the elemental's bracers, along with the remaining drops of Brine's potion, and place them on the brazier. The ritual should be enough to summon a pure spirit for you to communicate with.\n\nBring me proof the task is done, and I will reward you with your totem.", objectives = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64] = { id = 64, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgotten Heirloom", description = "It was horrible!  Verna woke me when she heard a ruckus in the fields.  The fields were full of hooligans.  We left in a rush and I forgot to pack my pocket watch.  Verna's pa gave me that watch on our wedding day and I feel just sick knowing those thieves have it.  I left the pocket watch in the wardrobe at the farmhouse.  Look for the field of pumpkins to the West -- you can't miss it.  If you bring it back to me, I'd sure be grateful!", progress = "Don't suppose you were able to get my watch?", completion = "My watch!  Thank you so much, kind sir! \n\nWe are but poor farmers and we have lost our land but please accept this reward as a token of our appreciation.", objectives = "Farmer Furlbrow wants you to retrieve his pocket watch from the wardrobe in his farmhouse at the pumpkin farm to the West.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65] = { id = 65, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Brotherhood", description = "The band of wretches responsible for driving the good people of Westfall from the land call themselves The Defias Brotherhood.  I need you to infiltrate this clan of thugs.  We need to know who heads up the cartel and where they are hiding out.  In Lakeshire, in the inn, there is a rogue by the name of Wiley who owes me a favor.\n\nTravel to Lakeshire in the Redridge Mountains, east of Elwynn, and find out what you can.", completion = "So, Stoutmantle sent you?  Well, I owe him.", objectives = "Gryan Stoutmantle wants you to talk to Wiley in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66] = { id = 66, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "Last night a horrible disturbance rippled through my veins.  I sensed that my granddaughter, Alyssa, was in great danger.  I consulted the cards and Death stared up at me from the table.\n\nAfter taking a long journey through a dark trance I was able to uncover a clue to this terrifying mystery.  A name came to me, the name of Stalvan.\n\nSeek out the Clerk in the Town Hall and see if you can find out more about this character.  I fear for us all.", completion = "Ah so Madame Eva sent you. . . .", objectives = "Seek out the Clerk Daltry in the Darkshire Town Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[67] = { id = 67, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Legend of Stalvan", description = "Stalvan, eh?  Let me check the town registry.\n\nStalvan. . .Stalvan. . .let's see.  Ah, here we go!  I have a record of a Mr. Stalvan Mistmantle.  The last recorded address is the Moonbrook Schoolhouse.  My, talk about outdated!\n\nDo me a favor will you, friend?  If you happen to go out to Moonbrook, let me know if you get any update on this fellow.  I like to keep the records clean.", completion = "The old footlocker creaks open. . . .", objectives = "Travel to the Moonbrook Schoolhouse and bring back any updated information about Stalvan to Clerk Daltry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[68] = { id = 68, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "You find a Dusty Unsent Letter in the old footlocker.", progress = "Ah, I remember you.  You're the one who was asking about that Stalvan fellow.  Did you ever find what you were looking for?", completion = "Interesting.  So the chap did spend some time in Moonbrook after all.  It is rather odd the letter never got delivered.  Nonetheless, I shall update the registry.", objectives = "Take the Dusty Unsent Letter to Clerk Daltry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69] = { id = 69, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Legend of Stalvan", description = "Oh my!  Must have missed this the first time.  In the registry, right beneath the first address for Stalvan there's another one listed, only partially scratched out.  Looks like he was headed to The Lion's Pride Inn over in Goldshire.  Might want to check there, {name}.", completion = "Stalvan?  Sure sounds familiar.", objectives = "Go to The Lion's Pride Inn to see if anyone there has heard of the name Stalvan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70] = { id = 70, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "The name Stalvan rings a bell.  I remember now.\n\nMany years back, on a stormy night, a messenger came in, seeking refuge for the night.  Near the stroke of midnight, the man ran down the stairs screaming, his face pale with fear.  Still wearing his bedclothes, he disappeared into the downpour.\n\nIn his haste he forgot his letters in the chest upstairs.  He never returned for them. One remains from that Stalvan fellow, intended for the Canal District in Stormwind.  Help yourself to it.", progress = "What have ya got there?  Let me take a look at that. . .", completion = "You've got some nerve bringing this here.", objectives = "Retrieve Stalvan's Undelivered Letter from the chest and deliver it to the Canal District in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71] = { id = 71, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Thomas", description = "Now that you have both medallions, deliver them to Guard Thomas at the bridge so that he might know the fate of his murdered guards.", progress = "Hello, {name}.  Have you discovered the fates of Rolf and Malakai?", completion = "You have confirmed my fears, {name}.  The murlocs are a threat we cannot ignore.", objectives = "Deliver Rolf and Malakai's Medallions to Guard Thomas at the eastern Elwynn bridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72] = { id = 72, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "My father was the caretaker of the estate long before I was.  He had to mop the blood up after the massacre.  But that's neither here nor there.\n\nThe last funds of the Flintridge trust have dried up.  Now the last of the family possessions are headed for auction.  Blame the tax vultures.  I guess if you're really itching to learn more you're free to look through this junk.  Who knows what you might find.", completion = "You slowly slide the lid of the crate off. . . .", objectives = "Search through the packed up possessions for a clue.My father was the caretaker of the estate long before I was. He had to mop the blood up after the massacre. But that's neither here nor there.\n\nThe last funds of the Flintridge trust have dried up. Now the last of the family possessions are headed for auction. Blame the tax vultures. I guess if you're really itching to learn more you're free to look through this junk. Who knows what you might find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74] = { id = 74, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "Inside the crate you find various objects: musty heirlooms, a family portrait, a few hunting trophies and some old books.  Near the bottom, underneath a ceramic vase, you uncover A Torn Journal Page.", progress = "What have you got there?  I cannot see.  My eyesight is very bad.  Put it in my hands.", completion = "I can barely make out those letters.  But that writing style reminds me of something I once saw before my vision became so poor.", objectives = "The Torn Journal page you discovered provides your next clue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75] = { id = 75, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "There was a bundle of parchments in the chest upstairs when I moved into this place.  I looked at them once when I first arrived but I gave up once the fog hazed over my peepers. \n\nDo an old, nearly-blind man a favor and check the chest upstairs for anything that might help you in your quest to discover more about this Stalvan character.  I'm pretty sure there's a faded journal page that might be of interest to you.  Bring it to me and I'll help in anyway I can.", progress = "Did you find that page I mentioned, {name}?", completion = "You found it!", objectives = "Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76] = { id = 76, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jasperlode Mine", description = "Thanks to you we know the Fargodeep Mine is infested with kobolds.  Now we need a scout to investigate the more distant Jasperlode Mine.\n\nExplore Jasperlode and confirm any kobold presence.  To reach the mine, travel east along the road until you reach the Tower of Azora.  From the tower, head north and you'll find the mine in the foothills.", progress = "Hail, {name}.  What do you have to report? Have you scouted the Jasperlode Mine?", completion = "Kobolds at the Jasperlode Mine, you say?  Curses!  The situation is worsening by the minute!\n\nThank you for the report, {name}.  But I wish that the news you brought was good news.", objectives = "Explore the Jasperlode Mine, then report back to Marshal Dughan in Goldshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77] = { id = 77, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sticky Situation", description = "I possess original packaging materials for the ripple Dran Droffers seeks.  I will assist you in packaging the ripple for Malton's abrasive father... for a fee of two additional bottles of said ripple.  They are located in crates found in the abandoned Horde base near Skulk Rock.\n\nIt will be an arduous task, to wit; foul slimes and oozes will be found sticking to the ruins; rumor has it they are led by some sort of master ooze.  Regardless, procure the ripple and return to me here for packaging.", progress = "I trust that your arrival here at our camp is to deliver the bottles of ripple that are integral to the task at hand, yes?", completion = "Finely executed, {name}.  I am glad you had enough foresight not to bruise the delicacy of the ripple.  There is nothing worse than the bouquet of ripple that has been jostled about needlessly.\n\nIt will take a moment for the magic to be wrought over this precious cargo.  Actually, no magic is involved; I merely have some empty packaging for Hinterlands Honey Ripple.  Our chicanery shall turn these bottles into an alcoholic treasure of the ages.\n\nOnward - for great booze!", objectives = "Recover 10 bottles of Hinterlands Honey Ripple from the crates located around the abandoned Horde base in Skulk Rock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78] = { id = 78, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "I know of someone who might be able to assist you.  Back when I was leading the Stormwind Guard, we used to get drinks at the Scarlet Raven Tavern in Darkshire.  The Innkeeper there, Smitts, was quite an expert on the local lore.  Show him this page and see what he has to say about it.", progress = "Marshal Haggard sent you?  Why didn't you say so? \n\nAh, good ol' Haggard.  Poor chap is going to be completely blind before long.  Anyway, let me see what you've got there.", completion = "By the Light!  You bet I recognize that handwriting.", objectives = "Take the Faded Journal Page to Tavernkeep Smitts at Darkshire in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79] = { id = 79, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "I followed the legend of that Stalvan character for years.  When those visiting nobles were slaughtered a few years back I went with Haggard to investigate.  I found these muddy pages but we were never able to link the handwriting to that crazy man in the woods.  Your trail of evidence proves his guilt.  Take this to Commander Ebonlocke immediately and fill her in on what you've discovered!", progress = "This better be good, {class}.  Let me see what you have and tell me your tale.  But by the Light, be quick about it.  Darkshire's defense is my number one priority.  I have not the time to squander on dead-end leads.", completion = "My, you have proved yourself to be quite a detective, {class}.", objectives = "Take the muddy page to Commander Ebonlocke.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80] = { id = 80, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "I have had my eye on that creep, Stalvan, for quite sometime.  But if this page was written by the same hand it proves his guilt beyond a shadow of a doubt.\n\nIn all his days keeping the Town Registry, Clerk Daltry has become an expert at identifying handwriting.  Show him this page and see if the writing matches that of the registry signature.", progress = "Back again, {name}?  What do you have this time?", completion = "Why yes!  The writing on this page does in fact match that of the registry signatures.", objectives = "Show Clerk Daltry the Bloodstained Journal Page.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81] = { id = 81, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ripple Delivery", description = "I have taken the extra step of securing not only Dran's packaged ripple in the barrel, but also the extra bottles of ripple he is purloining.  While I may not hold Dran very highly, there is nothing worse than jostled ripple.  You're welcome.\n\nNow, deliver yon barrel to Dran Droffers in his salvage emporium in Orgrimmar.  Pray tell, please extend my warmest greetings to Malton; let him know that should he ever thirst for fine drink and finer drinking companions, we would be honored with his visit.", progress = "If you're not here to buy anything, and you're not here to deliver anything, then you're wasting my time!  You better have that ripple!", completion = "Well, let's see what's in this barrel!\n\nYes, yes, it looks as though it is all here.  Here's your fee for the package, good job on that.  I stand to make five times that fee when I sell it to the tavern!  Har har!\n\nThese extra bottles of Hinterlands Honey Ripple are going to be set for a special occasion.  I think I'll drink some with champagne.  I'll call it... champipple.", objectives = "Deliver the barrel to Dran Droffers in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82] = { id = 82, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noxious Lair Investigation", description = "All right now, these reports about the bugs... what we know is that they are draining the water pools that used to be where the Noxious Lair is. What we DON'T know is, well, everything else.\n\nLet's figure out who our enemy is first! I want you to head into the Noxious Lair and get some parts off of those critters. Get five from the Centipaar there and bring them to Alchemist Pestlezugg for him to dink with. With him on the case, we'll figure out what they are!", progress = "You're Junior Surveyor {name}, yes?  Quickly now, there is a dire situation at hand!  Do you have the insect parts that Fizzledowser said you would?!", completion = "Good work - I'll start my analysis on these now!  I can tell you right from the start though... these are nothing like any insect form I have ever seen.  It's almost as if these bugs are being controlled by an outside force or something.\n\nYou need to go talk to Fizzledowser right away; apparently there is an emergency that he needs your help with on the double!  I'm not sure, but I think it involves more of the bugs in the Tanaris desert!", objectives = "Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83] = { id = 83, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fine Linen Goods", description = "The thugs in Elwynn wear linen which I can use to make fine linen goods.\n\nBring me linen scraps and I'll use them to fashion something for you.\n\nYou'll find those lawless criminals in pockets across Elwynn Forest.", progress = "I'm running low on linen, {name}.  Do you have any for me?", completion = "Ah, these are nice scraps, if a little rough...\n\nHere you are!", objectives = "Bring 6 Linen Scraps to Sara Timberlain at the Eastvale Logging Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84] = { id = 84, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Billy", description = "Here you go.  And when you give this pie to that Billy, you tell him I hope he chokes on it!", progress = "Ugh... I'm starving!  Do you have that pie for me, {name}?", completion = "Mm, yum!  This pie is the best!\n\nI think my memory is coming back to me...", objectives = "Bring the Pork Belly Pie to Billy Maclure at the Maclure Vineyards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[85] = { id = 85, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Necklace", description = "I lost my necklace and I think that guttersnipe Billy Maclure took it!  He's usually scuttling like a rat around the Maclure Vineyards east of here. \n\nGet my necklace back for me and you'll warm an old widow's heart.", completion = "You lost a what?  Well I didn't take no necklace, because I ain't no thief!\n\nI might know who did but...<grin>...I'm too hungry to remember.", objectives = "Speak with Billy Maclure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86] = { id = 86, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pie for Billy", description = "Maybe if I got a pie, I could tell you who has that necklace.  And you know, I think that old Bernice lady at that other farm makes great Pork Belly Pies... \n\nMaybe if you gave her some tender boar meat from the boars that hang around our farms, and told her what it was for, she'd bake up a pie for you.", progress = "I don't think it's right feeding the boy who stole my necklace in the first place, but if that's what it takes to get back what's mine, then so be it!\n\nDo you have that boar meat?", completion = "Though this wild boar meat is bland, simmer it enough in the right spices and it sure does make for some tasty pie!", objectives = "Bring 4 Tender Boar Meat to Auntie Bernice Stonefield at the Stonefield's Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[87] = { id = 87, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldtooth", description = "I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace.  Don't ask me how it got there...it wasn't me!\n\nWell anyway, I saw this big, gold-toothed kobold pick up the necklace and run back to his den above the mine.  Go find that kobold and you'll find the necklace, I swear!", progress = "Hello, {name}.  Have you found my necklace?", completion = "Oh, you found it!  Thank you, thank you dear!\n\nHere, take this.  It was my husband's and he always said it was lucky.  If only he didn't forget it on his last campaign! *sniff*", objectives = "Bring Bernice's Necklace to \"Auntie\" Bernice Stonefield at the Stonefield Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88] = { id = 88, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Princess Must Die!", description = "The Brackwells have a prize-winning pig, Princess. The sow is HUGE, and she got that way from sneaking over here and eating my veggies!\n\nIt just so happens that she's here now! Princess must die! Bring me her collar as proof of the deed and I'll give you something for your time!\n\nYou'll find Princess smack dab in the middle of our watermelon patch. Get her!", progress = "Did you see her yet?  Did you get her?", completion = "Thank goodness!  That pig was getting so big she'd have eaten our whole crop!  Thank you, {name}.\n\nNow, do any of these suit you?", objectives = "Kill Princess, grab her collar, then bring it back to Ma Stonefield at the Stonefield Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89] = { id = 89, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Everstill Bridge", description = "During the last orc invasion we were forced to smelt our iron down to make bullets, swords and armor.  We sent word to Stormwind for a new shipment of materials but a band of Redridge gnolls hijacked the caravan and ran off into the hills behind Lakeshire.\n\nNow we're coming up short on supplies to get this bridge rebuilt.  If you can bring me 5 iron pikes and 5 iron rivets, {name}, I'll make sure you're rewarded. \n\nNow let's get to work!", progress = "This bridge isn't going to build itself!  Now where are those iron pikes and iron rivets?", completion = "Great work, {name}.  These supplies will help the bridge effort immensely.  We'll get this beauty shored up in no time.", objectives = "Bring 5 Iron Pikes and 5 Iron Rivets to Foreman Oslow in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90] = { id = 90, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seasoned Wolf Kabobs", description = "Seasoned Wolf Kabobs are a house favorite!  Sure, I can make you some.  But first I'll need the supplies.  Bring me 10 Lean Wolf Flanks as well as some Stormwind Seasoning Herbs.  There are so many wolves here in the forest, I am sure finding the Flanks will be no problem.  For the herbs, seek out Felicia Gump in her canal district flower shop in Stormwind.", progress = "Were you able to find 10 Lean Wolf Flanks yet?  How about the herbs from Felicia in Stormwind?", completion = "Very nice work, {name}!  Enjoy the delicacy known as Seasoned Wolf Kabob!", objectives = "Gather 10 Lean Wolf Flanks and Stormwind Seasoning Herbs and return to Chef Grual in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91] = { id = 91, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solomon's Law", description = "An enemy of Stormwind has taken up residence in the eastern foothills of Redridge. This wicked villain uses the Arcane to spread terror and misery upon our town and our people. Under the name, Morganth, he conducts his evil business.\n\nMorganth now controls the Shadowhide Gnoll Clan to perform his biddings. As stated by the Law of Lakeshire, aiding a criminal of the Kingdom is punishable by death.\n\nThese vile gnolls must be killed!\n\nTurn in 10 Shadowhide Pendants to me, and you shall be rewarded.", progress = "Turn in 10 Shadowhide Pendants to me, and you shall be rewarded.", completion = "The Court of Lakeshire recognizes your commitment to justice, {name}.  By enforcing the laws of the Kingdom you have helped uphold the justice of the land.", objectives = "Bring 10 Shadowhide Pendants to Bailiff Conacher in the Lakeshire Town Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92] = { id = 92, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redridge Goulash", description = "Nothing would please me more than to make you some Redridge Goulash. But there's a slight problem. During the recent orc uprising I fed the entire brigade of Stormwind troops. My cupboard is now bare. But if you can provide me with the ingredients, I'd be happy to oblige.\n\nJust bring me five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", progress = "I still need five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", completion = "Well done, {name}. Such fine specimens too! And here is your delicious delicacy known as Redridge Goulash!", objectives = "Chef Breanna of Lakeshire wants five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93] = { id = 93, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dusky Crab Cakes", description = "I'll let you in on a little secret - Dusky \"Crab\" Cakes are really made from spider legs!  I know it's a bit disgusting, but the cakes have a nice, tangy flavor and make great snacks!  Bring me Gooey Spider Legs and I'll whip you up a few of them.\n\nI hear Venom Web Spiders are a good source - they nest to the north, between the foothills and the river.", progress = "Hail, {name}.  Did you get those Gooey Spider Legs yet?", completion = "Ah yes, a nice clutch of legs you have there!  Let me just get these seasoned with my secret spices (no looking!) and get them to skittering on a skillet for a while...\n\nAnd, although Dusky Crab Cakes are my specialty and I won't give out the recipe, here's the recipe for a dish that's almost as good.", objectives = "Gather 6 Gooey Spider Legs and bring them to Chef Grual in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94] = { id = 94, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Watchful Eye", description = "My rival, Morganth, is a vicious mage of great power who lives in the Tower of Ilgalar in Redridge.  I have developed a means of spying on him, the Eye of Azora, and can now view him from afar.\n\nBut to study his thoughts ... I require further aid.\n\nIf you are willing, then take my Glyph of Azora to the Tower of Ilgalar.  Place it upon the Lion Statue near the Tower.\n\nWhen this is done, the power of Azora will grant visions of Morganth's future plans.", progress = "This Lion Statue has sat here for decades, and keeps a lonely watch over the infamous Tower of Ilgalar.\n\nThere is a depression at the base of the statue, where a gem or glyph might be set...", completion = "You place the Glyph of Azora on the stone.  It adheres itself ... and you hear from it Theocritus' disembodied voice:\n\nYou have my gratitude, young {name}.  You may now speak with me through this Glyph, and I might have future tasks for you ... after I have probed the thoughts of my rival.", objectives = "Take the Glyph of Azora to the Lion Statue near the Tower of Ilgalar in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95] = { id = 95, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sven's Revenge", description = "I used to work one of the farms to the southeast...until Dark Riders from Deadwind Pass descended upon my farm and slaughtered my family when I was away!\n\nWhen I returned I saw a shadowy figure skulking near my barn, burying something.  He fled before I could catch him, and I couldn't linger for I was hot on the heels of the Dark Riders.  So I never discovered what was hidden.\n\nIf you can find what that shadowy figure buried, I would be grateful.  The hiding spot is behind the old stump near my barn.", completion = "A mound of dirt is here, hastily piled up as if someone had need of hiding something...without much time to do it.", objectives = "Go to Sven's Farm and find what was buried behind the old stump.I used to work one of the farms to the southeast...until Dark Riders from Deadwind Pass descended upon my farm and slaughtered my family when I was away!\n\nWhen I returned I saw a shadowy figure skulking near my barn, burying something. He fled before I could catch him, and I couldn't linger for I was hot on the heels of the Dark Riders. So I never discovered what was hidden.\n\nIf you can find what that shadowy figure buried, I would be grateful. The hiding spot is behind the old stump near my barn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[96] = { id = 96, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Take shard. Take shard and give life.\n\nGive life and understand. Understand water is life... corruption stops life.\n\nYou protect and give life with water's power.You will learn:", objectives = "Bring the Shard of Water to Islen Waterseer at the Tidus Stair in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[97] = { id = 97, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Legend of Stalvan", description = "Let Commander Ebonlocke know immediately that the handwriting matched, {name}!  Her suspicions were correct!", sourceObjective = "Report the news to Commander Ebonlocke.", completion = "I knew it!  Fine work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[98] = { id = 98, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Stalvan", description = "Stalvan Mistmantle led a life of depravity.  Innocent victims died by his hand.  Undoubtedly he is guilty of countless crimes.  Now the lunatic threatens Darkshire.  The Light only knows what sordid acts he is plotting.  Travel to his cottage just north of town, {class}, and execute Stalvan, once and for all.\n\nWhen the deed is done, travel to Madame Eva's and show her his family ring.  After all, it was her premonition that led to this gruesome discovery.  But Darkshire is safer because of her.", progress = "Yes, {name}?", completion = "I know, {name}: Stalvan is dead.  I sensed a wave of hope ripple through the tainted forest.  Once and for all, Duskwood is free from his blood thirst.  My joy is hampered by thoughts of those who fell prey to the horrible beast.  Nonetheless, you are a brave and cunning {class}.", objectives = "Kill Stalvan Mistmantle and show Madame Eva his family ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[99] = { id = 99, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugal's Folly", description = "As my understanding of Arugal's magic grows so does my disdain for the hapless fool.  I am close to completing my research on his so called remedy.\n\nMy knowledge will be complete when I learn what enchantment is causing the strange behavior going on in Pyrewood Village.  By day, the peasants appear to be Human.  But when the sun goes down the townsfolk turn into Moonrage Worgen.\n\nI need to draw energy from the enchanted shackles Arugal cast on them.  Bring to me six enchanted Pyrewood Shackles, {name}.", progress = "Have you secured the Pyrewood Shackles yet, {name}?", completion = "Your persistence is commendable.  With the knowledge you helped me gather, Arugal will fall and his reckless magic shall be undone.  Cheers to you, {name}.", objectives = "Bring 6 Pyrewood Shackles to Dalar Dawnweaver at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[100] = { id = 100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Light explodes as you finish the incantation. The sounds of the water drops hitting the flame have died down and your senses are overcome as the corrupt spirits around you are destroyed.", sourceObjective = "Speak to the Minor Manifestation of Water at North Tide's Run in Silverpine Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[101] = { id = 101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Totem of Infliction", description = "As the mystical taint creeps through the forest, the need for self-protection is undeniable, {name}.  The winds whisper to me and they speak of a great danger which waits patiently for you in the near future.\n\nIf you wish to protect yourself, noble {class}, bring to me 10 ghoul fangs, 10 skeleton fingers and 5 vials of spider venom.  For you I shall enchant a Totem of Infliction which will harm those who attempt violent acts against you.", progress = "Bring to me 10 ghoul fangs, 10 skeleton fingers and 5 vials of spider venom.  For you I shall enchant a Totem of Infliction which will harm those who attempt violent acts against you.", completion = "Very wise of you, {name}.  This Totem of Infliction will help to protect you against the evil which lurks throughout Azeroth and beyond.  When you feel threatened, hold this totem and take comfort in its magical aura.  Be brave, fair {class}.  You will need all the courage you can muster for I see much bloodshed in your future.", objectives = "Bring 10 Ghoul Fangs, 10 Skeleton Fingers and 5 Vials of Spider Venom to Madame Eva in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[102] = { id = 102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrolling Westfall", description = "Stormwind has abandoned us.  A foul wind of depravity rustles through the plains of Westfall.  This was my homeland and I will not turn my back on the citizens who choose to remain here.  We, the former farmers, shall make our stand.\n\nYour task, should you choose to accept, is to patrol the grasslands of Westfall.  Track down and slay the vile Gnolls that seem to be working in conjunction with the Deadmines thieves. Bring me eight Gnoll Paws and I will reward your bravery.", progress = "Have you collected 8 paws from those treacherous Gnolls yet?", completion = "Well done, {name}.  With valiant adventurers such as yourself fighting alongside The People's Militia, Westfall just might return to the prosperous breadbasket it once was.  Please accept this in recognition of your tireless efforts.", objectives = "Bring 8 Gnoll Paws to Captain Danuvin on Sentinel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[103] = { id = 103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeper of the Flame", description = "The night the Lighthouse Keeper's family died was horrible.  I watched, helpless, as Old Murk-Eye led the attack.  But what's done is done and now my concern is for the lives of the sailors on The Great Sea whose ships come close to the perilous rocks of the coastline.  With no one to keep watch on the flame the responsibility has fallen upon me.\n\nHelp me keep the torch lit by bringing me 5 flasks of oil from the Harvest Monsters.", progress = "The flame will not burn for long without oil, {name}.", completion = "Praise you, brave {class}.  The rocks of the Westfall Coast shall be lit thanks to your hard work.  Many lives will be spared so long as the torch is kept lit.\n\nI died needlessly on this very shore.  My afterlife plight is to see that no others follow my destiny.", objectives = "Bring 5 Flasks of Oil to Captain Grayson at the Westfall Lighthouse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[104] = { id = 104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coastal Menace", description = "When my life was ended upon the rocks, I had no clue what the afterlife held for me.  The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off.  They returned and re-lit the flame but Old Murk-Eye coerced the weaker minded murlocs to raid the Lighthouse with him once again.  The second time the family was not so lucky and before my eyes they perished helplessly.\n\nSlay Old Murk-Eye if you see him along the shore and bring me one of his scales and I shall reward you.", progress = "Have you laid waste to the menace known as Old Murk-Eye yet?  He has been spotted roaming the coastline of Westfall.\n\nReturn to me when the foul beast is dead.", completion = "So the foul heathen, Murk-Eye is dead.  Well done, {name}.  By your hands one life was laid to rest but perhaps many more were saved.  The Great Sea, wrought with danger as it is, shall be a wee bit safer this night thanks to your heroics.", objectives = "Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[105] = { id = 105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alas, Andorhal", description = "Alas, the time to attack Andorhal and drive out the lich that controls it is upon us!\n\nInside the ruins of the city is where the lich - Araj the Summoner - holds dominion.  He is guarded by numerous Scourge surrounding the remains of city's center, and his personal retinue of guardians attached to him directly is formidable.  You will need numerous allies to even stand a chance of facing him successfully.\n\nDestroy Araj, {name}, and bring me a shard from his phylactery as proof!", progress = "Your task has been given to you, {name}.  Do you have a shard from the lich's phylactery as proof of the task being accomplished?", completion = "You've done it!  Araj... the lich is finally defeated!\n\nYou've done a tremendous service to the Horde on this day, {name}.  Your bravery and perseverance are a testament to what it means to be a true hero.  Please - accept this as a token for all to see and know that you have delivered the Horde a victory for the ages!", objectives = "Bring Araj's Phylactery Shard to High Executor Derrington at the Bulwark, Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[106] = { id = 106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Young Lovers", description = "Oh, I'm cursed!  My heart belongs to Tommy Joe Stonefield, but our families are bitter enemies.  So I can't see him, even though my eyes ache to gaze upon that handsome face!\n\nPlease, take this letter and give it to Tommy Joe.  He's usually at the river to the west of the Stonefield Farm, which is due west of here.", progress = "You have what??  Maybell is the light of my dull life.  Hurry, let me see her letter!", completion = "Ah!  I can't stand us being apart.  I have to see her!!", objectives = "Give Maybell's Love Letter to Tommy Joe Stonefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[107] = { id = 107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Note to William", description = "I bet William Pestle has a potion to unite our two young lovers!\n\nHere, take this note to William.  He's staying at the Lion's Pride Inn in Goldshire.", progress = "You have a note from \"Gramma\" Stonefield, eh?  I haven't seen Mildred in years!  I wonder what she has to say...", completion = "My heart goes out to those two poor souls, Maybell and Tommy Joe.  I remember being young and in love, once.\n\nThere must be something I can do to help them!  Let me think...", objectives = "Take Gramma Stonefield's Note to William Pestle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[109] = { id = 109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Gryan Stoutmantle", description = "Looks to me you've seen quite a bit of combat in your time, {class}.  If you haven't already, you should report to Gryan Stoutmantle.  He heads up the People's Militia, aimed at protecting the farmlands of Westfall.  I bet he could use your help.  You can usually find him in the stone tower on Sentinel Hill, just off the road in the middle of Westfall.", completion = "Ah, so my friend sent you here?  How kind.  \n\nWell the Stormwind Monarchy has abandoned our cause.  Now it is up to the People's Militia to keep the land free from corruption.  If our cause interests you, I can put your combat skills to use in the name of freedom.", objectives = "Talk to Gryan Stoutmantle. He usually can be found in the stone tower on Sentinel Hill, just off the road, in the middle of Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[110] = { id = 110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insect Part Analysis", description = "I'm going to spend some time taking a look at Scrimshank's surveying gear... as well as putting his personal effects in order.  I get the sneaking feeling behind my ears that this isn't the last loss we'll be facing against these bugs.\n\nI'd like for you to check in with Alchemist Pestlezugg to see if he has had a chance to process the insect parts we sent him.  If they're ready, bring them to me.", completion = "Yes, I have the results right here.  They are... unsettling, to say the least\n\nOur initial suspicion that the bugs are being controlled by an outside force, we believe, is correct.  If this is the case, then we are dealing with not only a very powerful unknown force, but also a malignant one.  These bugs have been changed to be pure ravagers.  I've never seen anything quite like it.", objectives = "Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[111] = { id = 111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Gramma", description = "Please, {name}, talk with my Gramma.  If anyone can find a way to bring me together with Maybell, she can.\n\nShe's inside our house east of here.", completion = "While our families are feuding, Tommy Joe and Maybell don't have much of a future, but... maybe we can get them together for just a little while.\n\nHm, what can we do...", objectives = "Speak with Gramma Stonefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[112] = { id = 112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collecting Kelp", description = "I can make an invisibility liquor for Maybell, so she can slip away from the Maclure Vineyards and go to Tommy Joe.  But to make the liquor, I need some crystal kelp.\n\nAlthough the kelp usually grows in the ocean... sometimes murlocs collect it.  See if the murlocs near Crystal Lake have any.  Crystal Lake is just east of Goldshire.", progress = "Do you have that crystal kelp?  I'm sure Maybell is anxious to see her beau...", completion = "You got them.  Good show!  Now, just one moment while I concoct the potion...", objectives = "Bring 4 Crystal Kelp Fronds to William Pestle in Goldshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[113] = { id = 113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insect Part Analysis", description = "Senior Surveyor Fizzledowser needs to see this report immediately.  Actually... everyone who can read needs to see this report.  We are facing a grave and serious threat to not only Tanaris and Gadgetzan, but if left unchecked, the entirety of southern Kalimdor.  Heck, even quite possible the whole of Azeroth; this thing has given no indication it will subside.\n\nHave Fizzledowser make a duplicate of the report for you to distribute freely to your allegiance. Everyone must know about this threat!", progress = "Well Junior Surveyor {name}, has ol' Pestlezugg got that report ready yet?", completion = "Thank you for delivering the report, Junior Surveyor {name}; here is your pay for your diligent service to the Gadgetzan Water Company.\n\nWhile I am usually not thrilled about handing out our valuable information carte blanche to those who would otherwise pay good coin for it, I've known Pestlezugg for a number of years now.  If he recommends letting everyone know about it, then so be it.  Give me a moment and I'll make you a copy.", objectives = "Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan. Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[114] = { id = 114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Escape", description = "Take this invisibility liquor to young Maybell.  It should last long enough for her to visit Tommy Joe.", progress = "Did you deliver my letter to Tommy Joe?  What did he say??", completion = "Oh...my!  I feel guilty deceiving my family, but my feelings for Tommy Joe are too strong to ignore.\n\nThank you, {name}.  I'll drink this liquor as soon as I have the chance and sneak away to my love.\n\nAnd for you... please take this.", objectives = "Take the Invisibility Liquor to Maybell Maclure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[115] = { id = 115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Magic", description = "The Blackrock orcs enlisted shadowcasters to aid their attacks in Redridge, and they have brought with them devices of dark power--midnight orbs.  These orbs have struck telling blows against Redridge's defenders, and it's imperative we remove the demon-tainted items from the conflict.\n\nFind and deliver to me midnight orbs from slain Blackrock shadowcasters.  I will then have them disposed of, for this world would be a better place without them!", progress = "How goes your conflict with the shadowcasters?  Did you find the midnight orbs?", completion = "Thank you, {name}.  I'll send these to be destroyed immediately.", objectives = "Bring 3 Midnight Orbs to Marshal Marris in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[116] = { id = 116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dry Times", description = "I find myself in quite a pinch here, {name}.  The bottles are close to running dry.  The latest booze shipment is long overdue.  The orc invasion has been hell.\n\nPerhaps you can go to work for me?\n\nI need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.", progress = "I need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.", completion = "A job well done, {name}!  I know well the roads you had to journey to procure this fine array of liquor.  But my patrons will be happy once again! \n\nMy wife is quite a seamstress.  Please accept this cloak she made in return for your services.", objectives = "Barkeep Daniels of Lakeshire needs a keg of Thunderbrew Lager, a cask of Merlot, a bottle of Moonshine and a skin of Sweet Rum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[117] = { id = 117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderbrew Lager", description = "Hurry, my friend, move with haste \nIn order for our rich lager to taste \nMore like beer and less like stew, \nHops are needed to make the brew.", progress = "Hurry, my friend, move with haste \nIn order for our rich lager to taste\nMore like beer and less like stew,\nHops are needed to make the brew.", completion = "Hops and Barley, yeast and malt \nThe taste-buds feel a virtual assault, \nNo need to plead, no need to beg \nFor Thunderbrew Lager comes in a keg!", objectives = "Bring Grimbooze Thunderbrew 5 hops to complete his special brew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[118] = { id = 118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Price of Shoes", description = "I've been using so much iron keeping the Stormwind Guards outfitted, I don't have enough to supply the stable's horses with shoes!\n\nTake this note to Blacksmith Argus in Goldshire.  It explains to him my problem and requests a shipment of horseshoes.", progress = "What's that?  Verner sent you, you say?  Well give me his note.  And SPEAK UP!", completion = "Heh, so old Verner needs some shoes, does he!?!", objectives = "Take Verner's Note to Smith Argus at Goldshire in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[119] = { id = 119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Verner", description = "Ok, I'll give him his 50 horseshoes...\n\nHere they are, all boxed up and ready to go!  Tell Verner it was a pleasure doing business, and be sure he reads the note attached to this crate!", progress = "Great, you're back!  Did you get the shoes?", completion = "Thank you, this really helps me out.\n\nBut what's this?  Argus sent a note with the crate...What??  Argus wants me to PAY him?  Bah!\n\nWell, {name}, thank you for your help.", objectives = "Return to Verner Osgood at Lakeshire in Redridge. Give him the Crate of Horseshoes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[120] = { id = 120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messenger to Stormwind", description = "These are trying times, {class}.  The township is under constant siege.  Without reinforcements, we will certainly face defeat.  The message I now entrust to you is of utmost importance.  Get this report to General Marcus Jonathan of Stormwind immediately.  Once your delivery is made, return to me at once with any news, be it good or bad. \n\nNow make haste!", progress = "What have you there?", completion = "At ease, {class}.\n\nMagistrate Solomon is a noble leader.  His words carry great weight with me.  I shall seek the counsel of the King and make the situation clear to him.  Assure the good judge that he has the Stormwind Army's support.  Reinforcements will be sent as soon as word is given from His Majesty.", objectives = "Magistrate Solomon has given you a report which must be delivered to General Marcus Jonathan in Stormwind. The judge wants you to return to him as soon as the delivery has been made.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[121] = { id = 121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messenger to Stormwind", description = "While I wait for a response from the King I want you to carry this letter to Magistrate Solomon. \n\nDismissed, {class}!", progress = "Did the General send news?  Are reinforcements on the way?", completion = "Thank you for your time, {class}.  For your service to Lakeshire and Stormwind I reward you with these coins.\n\nNow if you'll excuse me, I find this correspondence somewhat of a mystery.  Something is amiss in our Kingdom.  I fear this is the beginning of conflict, not the end.", objectives = "Take General Marcus Jonathan's letter of response to Magistrate Solomon in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[122] = { id = 122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underbelly Scales", description = "I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire.  If you can get 6 of them for me, then I can pay Argus with some... and have enough left to fashion something for you.\n\nBlack dragon whelps are often flying around south of Lakeshire, but they like to wander.  You might have to just keep an eye out and hunt them when you see them.", progress = "I know that greedy Argus will send someone to collect his scales if I don't give them to him soon.  Have you found those scales yet?", completion = "Thanks!  These will get me out of debt to Argus...", objectives = "Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[123] = { id = 123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Collector", description = "This note is a schedule with a list of days and times when a person -- described only as \"The Collector\" -- will receive a shipment of gold from the mines in Elwynn Forest.\n\nFrom the schedule, it looks as if the Collector resides near the Brackwell Pumpkin Patch in eastern Elwynn.\n\nThis sounds important.  You should report it to Marshal Patterson at Eastvale Logging Camp.", progress = "What?!?  We haven't had our people working the Elwynn mines for months!\n\nLet me see that note you have...", completion = "Hm... I have heard of this \"Collector\" but I don't know whom he's working for.  Thank you for the schedule.  It will help us solve this mystery.", objectives = "Go to Marshal Patterson at the Eastvale Logging Camp in Elwynn Forest and give him The Collector's Schedule.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[124] = { id = 124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Baying of Gnolls", description = "As if the attacking orcs weren't enough!  Now I have gnoll brutes and mystics prowling along the ridge north of my stable, taking my horses when they stray...\n\nIf you can get rid of those gnolls, my horses and I would be very grateful.", completion = "Thank you for all your help, {name}.", objectives = "Kill 10 Redridge Brutes and 8 Redridge Mystics, then return to Verner Osgood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[125] = { id = 125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Tools", description = "I could really use a hand here, {name}.  With the town under siege, it's been hard to get supplies.  My tools were being delivered from Goldshire by wagon but the bridge was blown out.  We put the tools in a boat but the orcs hit it with a catapult.  Just my luck, my toolbox sank right to the bottom of the lake.\n\nRetrieve my toolbox, {name}, and I'll make it worth your while.", progress = "Were you able to find my tools?", completion = "Excellent recovery, {name}!  I never thought I'd see these tools again.", objectives = "Foreman Oslow of Lakeshire wants you to retrieve his toolbox from the bottom of Lake Everstill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[126] = { id = 126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Howling in the Hills", description = "{name}, the gnolls are still out there.  I can hear their baying as they hunt in the hills above Lakeshire.  And one cry is louder than the rest - Yowler,  their leader.\n\nKill Yowler and send his pack scattering!  Bring me his paw as proof.\n\nAnd be careful, this gnoll is their leader for a reason.  He is no Mongrel...", progress = "Yowler is a dangerous creature, {name}.  If you're not ready for him, I understand.", completion = "Again, thank you for your help.  The Stormwind army is so busy dealing with the orcs, they don't have the troops to protect Redridge from local threats like the gnolls.", objectives = "Bring Yowler's Paw to Verner Osgood in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[127] = { id = 127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selling Fish", description = "Lake Everstill is famous for its spotted sunfish.  There's always demand for them...and I'm running low!\n\nBring me a batch of 10 and I'll barter well for them.  If you can't fish yourself, then...maybe you can get them off the murlocs!", progress = "You have some sunfish for me, eh?", completion = "Pleasure doin' business with you, matey!", objectives = "Bring 10 Spotted Sunfish to Dockmaster Baren in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[128] = { id = 128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Bounty", description = "The Blackrock Clan must be destroyed. The Enemy has invaded our lands. These mountains fall under the sovereign right of the King of Stormwind. Our sources tell us that the leaders of each unit within the Clan are known as Champions. You'll find them in their encampment to the north, just west of the road to the Burning Steppes.\n\nMagistrate Solomon wants these foul brutes dead. Slay 15 Blackrock Champions and return to me.", completion = "I see you have fought valiantly against the Blackrock Clan, {class}.  Your service to our township is great indeed.", objectives = "Kill 15 Blackrock Champions and Guard Howe in Lakeshire will reward you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[129] = { id = 129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Free Lunch", description = "Can you do me a favor?  I've prepared a lunch for Guard Parker, but he's out on patrol...he's a big, strong Stormwind guard who can defend himself, but it's much too dangerous out there for a townsperson like me.\n\nSo if you deliver his lunch for me, then come back here and I'll give you a free lunch!  Parker patrols the stretch of road leading to Duskwood.", progress = "Darcy sent me a lunch, did she?  Such a kind heart she has.  Well...let's have it!", completion = "Thanks, I could really use the meal.  Guarding Lakeshire from the orcs and gnolls is tough work!", objectives = "Bring Parker's lunch to Guard Parker. He patrols the road leading to Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[130] = { id = 130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visit the Herbalist", description = "Before you go back to Darcy, can you bring her some flowers for me?  You can get them at the herbalist shop back in Lakeshire, at the west end of town.\n\nBut when you get the flowers...don't tell the herbalist, Martie, whom they're from, or whom they're for...", completion = "You need a bouquet of flowers?  You haven't been in town very long...have you already found for yourself a sweetheart here?\n\nI know I shouldn't pry, but it's nice to see that love is in the air... especially in dangerous times like these.", objectives = "Speak with the Redridge Herbalist, Martie Jainrose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[131] = { id = 131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivering Daffodils", description = "Here is your bouquet.  I chose Daffodils for you.  They're my favorite!", progress = "Hello again, {name}.  Did Parker like the lunch I sent him?", completion = "Oh, those are lovely!  I can't wait to put them in some water!\n\nBut...these are Martie's favorite flowers.  Parker didn't have you go to that jealous vixen for this bouquet, did he?  You didn't tell her who they were for, did you?  If you did, then it wouldn't surprise me if she poisoned them.\n\nOh, but it's not your fault.  Thank you, and here's your meal.", objectives = "Give Darcy the Daffodil Bouquet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[132] = { id = 132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Brotherhood", description = "What I am about to tell you could cost me my life.  The Defias gang is up to something big.  Last I heard they were working in conjunction with various gnolls, kobolds and even goblins.\n\nTake this note to Stoutmantle.  It explains as much as I know on the subject.", progress = "Good to see you back, {name}.  What did Wiley have to say for himself?", completion = "Bah!  I should have let that scoundrel rot when I had the chance.  But this information is crucial.  Good work.", objectives = "Take Wiley's Note to Gryan Stoutmantle in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[133] = { id = 133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghoulish Effigy", description = "I live so far from the protection of town, it's a wonder the ghouls and the walking dead haven't eaten me!  In fact, just yesterday a pack of Bone Chewers was pounding on the walls of my house!\n\nI want to make an effigy - a kind of \"scarecrow\" for Ghouls.  To do that I need some Ghoul Ribs.  You can get them from Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones and Plague Spreaders.\n\nGet the ribs for me, and I will repay you with some coin.", progress = "I think I hear a pack of Ghouls scurrying around the back of the house - I better put that effigy up quick!  Did you get those Ghoul Ribs for me?", completion = "Ah, thanks.  These will do just the trick!", objectives = "Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[134] = { id = 134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Thieves", description = "A few weeks ago I was picking herbs far from my house, and a band of ogres attacked me!  I ran, and I was forced to leave behind a crate of precious tools and herbs.\n\nAfter they chased me off, the ogres swaggered back to the ogre mound in southern Duskwood.  I'm sure my crate is somewhere near the mound.\n\nPlease, {name}, retrieve this crate for me for I miss it sorely.", progress = "Do you have my crate?  If so, then please...give it to me quickly!", completion = "Thank the Nec-...well, thank YOU, {name}!  You have more than earned your reward.\n\nAha!  Happy!  Happy nights ahead!!", objectives = "Return Abercrombie's Crate to Abercrombie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[135] = { id = 135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Brotherhood", description = "I wonder what Wiley meant when he mentioned the Stonemasons.  Perhaps that was a slip of tongue.  Could the Defias gang be related to the Stonemasons?  Only one man would know for sure:  Mathias Shaw, head of SI:7. Show him Wiley's Note and see if he has anything to add to this growing mystery. If you have trouble finding Shaw, check the Barracks in Old Town.", progress = "What business do you have with me?  I am a very busy man. . .", completion = "This matter might be more complex than Stoutmantle realizes.", objectives = "Take Wiley's Note to Mathias Shaw in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[136] = { id = 136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave.  So my treasure is yours now, ye jest need to follow the clues. \n\nFirst ye need to find me footlocker.  It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck.  There be lots of shipwrecks but only one rusty anchor on the coast.  Find that anchor and you'll find me locker!  Look in there for the next clue.", completion = "The footlocker slowly creaks open.  Sand and water seem to be its only contents. But wait!  A small crab scurries out with a clue to the treasure in his claws!", objectives = "Find Captain Sanders' footlocker and search it for the next clue.If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave. So my treasure is yours now, ye jest need to follow the clues. \n\nFirst ye need to find me footlocker. It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck. There be lots of shipwrecks but only one rusty anchor on the coast. Find that anchor and you'll find me locker!  Look in there for the next clue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[138] = { id = 138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "The clue to the treasure reads: Good work, matey!  Now ye need to head due east.  East up the bluffs, east to the road.  Look for the ol' chimney ruins near the side of the road.  There you'll find an old barrel with your next clue.", completion = "Good work, treasure hunter!", objectives = "Find the old barrel near the ruined chimney and search it for your next clue.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[139] = { id = 139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "Searching through the barrel you discover another piece of parchment.  This one reads:  Now from this here barrel, face ye North.  Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs.  If ye poke around that jug, ye just might find what you're lookin' for.", completion = "You're on your way to the jackpot, treasure seeker!", objectives = "Search the empty jug next to the windmill for the next clue.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[140] = { id = 140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "Sure enough, deep within the Old Jug there is another clue to Sanders' treasure.  The ink has run in some places and the paper smells like whiskey but you can make out some of the text:  Now that ye found me ol' whiskey jug, you're almost to the treasure!  Just face West from the bottle and walk down to the shore.  Once ye get to the water, keep going!  Swim straight west till you find the island with me treasure chest!", completion = "The hinges on the old chest are rusty but they still work.  You force the chest open and take the booty.\n\nCongratulations!", objectives = "Locate Captain Sanders' chest and open it for your reward.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[141] = { id = 141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Brotherhood", description = "The Stonemasons' Guild was run by a man named Edwin VanCleef.  VanCleef was responsible for rebuilding Stormwind after the orcs razed it in the First War.  Apparently, VanCleef and his men were unhappy with their treatment by the King after the reconstruction was complete.  That just might explain a thing or two.\n\nI have written a more detailed account for your Master in Westfall.  Take this to him at once!", progress = "Did Master Shaw shed any light on things?", completion = "Edwin VanCleef. . .I know the name well.  To think that a man so industrious and talented could turn into such a scoundrel unnerves me.  I'll need further proof before I believe this.", objectives = "Take Shaw's report to Gryan Stoutmantle in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[142] = { id = 142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Brotherhood", description = "We need to discover the location of the Defias hideout.  {name}, my scout reports that a Defias Messenger has been seen on the roads between Moonbrook, the Gold Coast Quarry and the Jangolode Mine.  I want you to capture him.  If he resists, kill him and bring me whatever he is carrying.", progress = "{name}, were you able to gather any information?  Did you locate the messenger?", completion = "This is indeed firm proof that VanCleef is in charge.  Now all we need to know is where the Defias gang is hiding out.\n\nWe've had a stroke of luck while you were gone.  We captured a thief trying to steal Saldean's wagon.  He has promised to lead us to the hideout in exchange for his life.  I want you to defend the traitor so he can reveal the hideout.  Return to me once you have uncovered the location.", objectives = "Track down the Defias Messenger in Westfall and bring his message to Stoutmantle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[143] = { id = 143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messenger to Westfall", description = "Something odd is afoot with the Stormwind Army.  They should have been here in force by now.  Time is a luxury we don't have, however.  I will not stand by and watch the people of Lakeshire give their lives without trying to enlist more help.  I've heard word of a people's militia forming in Westfall.\n\nTake this plea to their leader, Gryan Stoutmantle.  Perhaps Stoutmantle's men can lend some support here until the King sends reserves.", progress = "Hail, {class}.  What business do you have with The People's Militia?", completion = "Good Messenger, you have served your master well.", objectives = "Magistrate Solomon wants you to take his written plea to Gryan Stoutmantle in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[144] = { id = 144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messenger to Westfall", description = "Magistrate Solomon's note pains me to read.  But it is obvious he knows not the war which is waged in Westfall or else he would know better than to expect aid from the Militia.  If Stormwind had not deserted us as well, we would not have the need for the Militia.\n\nTake this response to your master in Redridge, {class}.  And let him know that my heart is heavy with the loss of good men.", progress = "Shall we expect the People's Militia soon?  Does Lord Stoutmantle's news bode well?", completion = "I do say, this is not good at all.  I did not realize that Stoutmantle's situation was not unlike ours here in Lakeshire.  What action is so important that it calls the Stormwind Army away from its people?  Bah, I should not ponder aloud.\n\nHere, messenger.  Accept these coins in exchange for your service to the Township.  I might call upon you again.", objectives = "Return to Magistrate Solomon with Gryan Stoutmantle's response.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[145] = { id = 145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messenger to Darkshire", description = "I require your assistance once again.  I have written to Lord Ebonlocke, requesting that he sends his trained guards, the Night Watch, to help with Lakeshire's defense.  It is imperative this message makes it to him swiftly.  You must exercise extreme caution.  Ebonlocke is the mayor of Darkshire, in the heart of Duskwood.  Do not stray from the roads.", progress = "You appear to have traveled from afar, {class}.  What business do you have here in Darkshire?", completion = "Thank you for making the long journey here.  This is indeed important information.", objectives = "Magistrate Solomon wants you to take a letter to Lord Ebonlocke in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[146] = { id = 146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messenger to Darkshire", description = "If I did not know Magistrate Solomon personally, I would say the man has gone mad.  Send the Night Watch to Lakeshire because Stormwind refuses aid?  The Night Watch was formed because Stormwind left us when this foul magic seeped into the land.  If I sent my Night Watch, this town would be overrun by evil before the guards even reached the forest's edge.\n\nTake this letter of response to your Master in Lakeshire.", progress = "Ah, good to see you back, messenger.  Shall I inform the Marshal that the Night Watch is on its way from Darkshire?", completion = "By the Light!  The Stormwind Army retreated from Westfall.  And the Guard no longer protects Darkshire?  There is some treachery abound.  How could this be so? \n\nOh I forgot to reward your service, {class}.  Here are some coins.  Now excuse me.  Something is amiss in Stormwind and I must get to the bottom of it.", objectives = "Return to Magistrate Solomon with Lord Ebonlocke's letter of response.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[147] = { id = 147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manhunt", description = "If the \"Collector\" is taking gold from our mines then he's stealing from the kingdom!  Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me.  It may tell us whom the Collector is working for...\n\nThat Pickup Schedule says the Collector is hiding out at the Brackwell Pumpkin Patch.  You should search for him there.", progress = "Did you find the Collector?  Did you discover whom he's working for?", completion = "You found him?  Well done, {name}.  He won't be \"collecting\" from the Elwynn Mines again!\n\nAnd this ring you found is interesting... it's a membership ring for the old Stonemason's Guild in Stormwind. I haven't seen one of these in years, since back in the days when the Defias Brotherhood used to infest this land.", objectives = "Find and kill \"the Collector\"  then return to Marshal Patterson with The Collector's Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[148] = { id = 148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from Darkshire", description = "Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip.\n\nCan you go to Darkshire and bring me back some Ghost Hair Thread?  You can get it from Madame Eva at her home on the Darkshire square.", sourceObjective = "Speak with Madame Eva.", completion = "Ah, Ghost Hair Thread is what you need, is it?  I'm afraid I have none in stock, but I can make some for you...if you can supply the ghost hair.", sourceObjectiveStatus = "unverified-source-field" }
quests[149] = { id = 149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghost Hair Thread", description = "There is a poor, sad spirit, Blind Mary, who haunts an old farm house in the hills south of Darkshire.\n\nHere, take this Spectral Comb and ask Blind Mary to comb her hair.  Then bring back the comb and I will glean from it the Ghost Hair I'll need for the thread.\n\nAnd take care, for dark things now lurk near that house...", progress = "<Sob> Oh please, don't look at me!  I tore out these eyes with my own hands, but I can still feel your gaze!\n\nI'm hideous!  Hideous!  Please, look away!!", completion = "What is this?  A comb?  It's lovely!  And it glides through my hair as if it weren't the stiff, stringy horror that it is.\n\nOh, if only I had a mirror...", objectives = "Bring the Spectral Comb to Blind Mary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[150] = { id = 150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murloc Poachers", description = "Murlocs are becoming a problem.  Larger groups of the fishmen are dropping anchor along the shores of Lake Everstill and fishing up a storm!  We need them gone before they eat all the fish in the lake!\n\nHunt murlocs!  Bring me eight of their fins and I might have something for you...", progress = "Do you have those fins?  Hurry, we need those murlocs driven from the lake!", completion = "Well done, {name}.  I hope you didn't have too much trouble with those murlocs.\n\nIt's strange seeing them so far from the sea.  I wonder if they're here because they're running from something...", objectives = "Bring 8 Murloc Fins to Dockmaster Baren in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[151] = { id = 151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poor Old Blanchy", description = "Poor Old Blanchy!  Such a tired beast after all the work we put her through. I fed her before we left the farm, but we weren't expecting the wagon to break on us. If you could bring her a few handfuls of oats from the fields, I'd be grateful.\n\nI bet you could find some around all of the farms in Westfall, if you can steer clear of those horrific machines that have taken over. There are several farms southwest of here.", progress = "Old Blanchy is on her last leg.  Did you happen to find any oats for her?", completion = "Thank you so much, {name}!  Poor Old Blanchy will be so happy!", objectives = "Verna Furlbrow in Westfall wants you to bring her 8 Handfuls of Oats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[152] = { id = 152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coast Isn't Clear", description = "You probably noticed all of the shipwrecks along the coast.  The Great Sea is treacherous indeed.  The coast of Westfall needs to be kept clear, so that if sailors find their way to our beaches, they are safe.  The Murlocs are trouble though.\n\nKill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and I will see to it that you are rewarded.", completion = "Well done, {name}.  You have quite a knack for combat.  Thanks to you the Coast of Westfall is a safer place.", objectives = "Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and return to Captain Grayson at the Westfall Lighthouse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[153] = { id = 153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red Leather Bandanas", description = "The Defias Front is constantly shifting.  I've been following their movements for quite some time now.  On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear.\n\nBring me 15 of these Bandanas and I'll see to it you are rewarded.", progress = "Bring me 15 red leather bandanas and I'll pay you well.", completion = "Nice work, {race}.  Please accept one of these items as payment for all your hard work.", objectives = "Bring 15 Red Leather Bandanas to Scout Galiaan at Sentinel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[154] = { id = 154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return the Comb", description = "NO!!!!!\n\nTake it, take this comb away from me!\n\nI'm a monster, and no one will ever think me lovely again!", progress = "I sense that you have seen Blind Mary.  You have my Comb...?", completion = "I can make a spool of Ghost Hair Thread with this, and have a few strands to spare.  Here are some coins for those extra strands.", objectives = "Return the Ghost Hair Comb to Madame Eva in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[155] = { id = 155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Brotherhood", description = "So Stoutmantle sends a scrawny {race} like you to protect me?  Guess you'll have to do.  Better bring some friends too. \n\nYou know the deal, right?  You watch my back and I'll take you to the Defias hideout.  But you better be close by my side.  The Defias gang wants my head now.  If they see me with you, they'll try to kill me.\n\nLet me know when you and any friends you can round up are ready to go.", completion = "Most excellent, {name}!  VanCleef is as good as ours now that we know where he is hiding.", objectives = "Escort the Defias Traitor to the secret hideout of the Defias Brotherhood. Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[156] = { id = 156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather Rot Blossoms", description = "If you bring me some rot blossoms then I can brew you up a batch of zombie juice.\n\nrot blossoms grow in strange places.  In particular, I hear you can find them inside the skulls of Skeletal Horrors and Skeletal Fiends... not that I've gotten close enough to look!\n\nThe Raven Hill Cemetery is lousy with those skeletons.  You may as well get rid of them while you're looking for rot blossoms.  The town of Darkshire would be grateful.", progress = "Hi, {name}.  Do you have those rot blossoms for me yet?", completion = "Good,  you got the rot blossoms.  And I'll tell Althea Ebonlocke of the Night Watch that you were killing skeletons.\n\nKeeping the people of Darkshire safe is a grim burden for the Night Watch, and news that others are helping stem the tide of fiends in Duskwood is welcome news indeed.", objectives = "Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[157] = { id = 157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver the Thread", description = "Here is your thread, {name}.  It has a thousand uses, from binding evil spirits to sewing life into inanimate objects.", progress = "I need to string the Ghost Hair Thread along my door and my windows to keep out unwanted spirits.  Did you get it for me?", completion = "Delightful!  This will do splendidly...\n\nHere, good {name}, take this as payment for your honorable deed.", objectives = "Bring the Ghost Hair Thread to Abercrombie, in his shack north of the Raven Hill Cemetery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[158] = { id = 158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zombie Juice", description = "I need a bottle of a certain liquor - Zombie Juice.  Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.\n\nAnd please hurry, {name}.  These nights get cold, and I need that drink to put fire in my veins again!", completion = "You need some Zombie Juice, do you?  Hmm...that's some strong stuff - I don't usually get requests for it.", objectives = "Speak with Tavernkeep Smitts.I need a bottle of a certain liquor - Zombie Juice. Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.\n\nAnd please hurry, {name}. These nights get cold, and I need that drink to put fire in my veins again!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[159] = { id = 159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juice Delivery", description = "Here's your Zombie Juice...\n\n...and be careful with this stuff.  It's strong enough to raise the dead!", progress = "I need that Zombie Juice to keep me warm on these cold, dark nights.  Did you get it for me?", completion = "A thousand thanks, {name}.  You warm an old man's heart with your foolish-...I mean...with your kindness!\n\nHere you are, friend.  Take this as a token of my gratitude.", objectives = "Bring the Zombie Juice to Abercrombie at his shack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[160] = { id = 160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Note to the Mayor", description = "Take this note to Ello Ebonlocke, the Mayor of Darkshire.\n\nHe and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!", progress = "Abercrombie...?  I don't know a person of that name.  You say you have a letter for me from this Abercrombie fellow?\n\nWell let's have it then...", completion = "<Ello looks at the letter...>\n\nWhat language is this?  It looks ancient...I can't read it.", objectives = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[161] = { id = 161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Threat Looms", description = "If my suspicions are correct, this is some type of explosive powder. This must be analyzed by an explosives expert so we know just what we're dealing with here.\n\nThere's only one man for the job. Ashlan Stonesmirk was assigned to monitoring the ogres at the Mo'grosh Stronghold to the east. Head that direction and locate him so that he can shed some light on what this substance is.", progress = "You say somethin', sonny?  Can't hear a bloody thing besides the ringin' in me ears.  Say, what's that you got there?", completion = "Ah, well Ol' Hinderweir is wise to be worried.", objectives = "Chief Engineer Hinderweir wants you to take the strange smelling powder to Ashlan Stonesmirk, the explosives expert at the Mo'grosh Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[162] = { id = 162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise of the Silithid", description = "I urge you to take this report to someone who has working knowledge in this kind of thing.\n\nI know this night elf scholar named Gracina Spiritmight.  She's spent a lot of time studying life forms that are unique to the ecology of Azeroth; she's a historian to boot!  If you want someone to help figure out what exactly this threat is, and more importantly how to stop it, give her the report.  We'll need the help.\n\nLast I heard, she was residing in the Temple of the Moon, located in Darnassus.", progress = "Peace and tranquility be upon you, stranger.  Why have you sought me out this day?", completion = "This report... we night elves know of the terror mentioned here.  Fizzledowser was wise to send this, and you, to me.\n\nThese creatures will consume the Tanaris desert rapidly; they are nothing short of one of the greatest menaces we all will ever face.  Familiarize yourself with this name, {name}: silithid.  The insects mentioned here are the silithid, and they are the tools of one of the greatest threats that both the Horde and Alliance face.\n\nIf only we were smart enough to see that before.", objectives = "Take the Insect Analysis Report to Gracina Spiritmight in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[163] = { id = 163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raven Hill", description = "Something's amiss at Raven Hill, {name}. Calor swears that someone--or something--is haunting the buildings there. Two nights running he's noticed the shadows moving, and the third before that he says he saw light in one of the windows.\n\nIf, as you say, you care about the safety of Duskwood, find out what monster haunts in Raven Hill.", completion = "No! Please don't kill me! It's just me... Jitters!! They're everywhere... I can't escape them! Monsters in Raven Hill? N-n-n-o... couldn't be. Only harmless Jitters.", objectives = "Find out what is haunting Raven Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[164] = { id = 164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliveries to Sven", description = "Do you know Sven? Now, there is a man who does the work of the Light! He and his followers keep a camp at the northwestern edge of Duskwood.\n\nUnfortunately, because they are so few, they cannot even spare a man to fetch supplies from town. Will you deliver these supplies to him?", progress = "You look a sturdy type, {class}. Have you come to join our fight?", completion = "These supplies will be most useful. The aid of the Carevin family is always appreciated. Here is a little something for your trouble.", objectives = "Deliver the supplies to Sven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[165] = { id = 165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit", description = "There was an old man who used to come into town to buy supplies rather frequently, but I haven't seen him for quite some time now. He lives out in a shack overlooking Raven Hill cemetery, if I remember correctly. Perhaps you should go see if something is amiss.", completion = "Elaine Carevin? Hehe, oh yes... of course, the Carevins.\n\nNo, nothing's wrong but it is hard for me to go into town now. The roads are dangerous and I'm not getting any younger. Maybe you can do an old man some favors?", objectives = "Check on the old man in the shack near Raven Hill cemetery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[166] = { id = 166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Brotherhood", description = "There is but one task left for you to complete.  Edwin VanCleef must be assassinated.  While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all.  Bring me the villain's head once the deed is done.", progress = "How goes the hunt for Edwin VanCleef?", completion = "{name}, your bravery is remarkable.  The People's Militia thanks you for your service to the people of Westfall.  With VanCleef dead, this marks the beginning of the end for the Defias Brotherhood.  Hopefully some day soon peace will once again grace the plains of this fair land.\n\nI salute you, Sir!", objectives = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[167] = { id = 167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Brother. . .", description = "We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us. I got out but the others... well... the others haven't been heard from.\n\nYou look like you might have better luck in there. If you could look for my brother, I'd be thankful.  He always carried his Explorers' League Badge. If you can't find him, that badge would at least give me some peace of mind.", progress = "Did you find any sign of my brother?  Is there any hope after all this time?", completion = "My suspicions were correct.  My poor brother.... Well, thank you for bringing some conclusion to this mystery, even if the conclusion was grim.", objectives = "Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[168] = { id = 168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collecting Memories", description = "Many of my friends perished that horrible day when the mine tunnel caved in.  If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them.  If you come across any of their Miners' Union Cards, bring them back to me and I'll make sure their families get some resolution from this horrible accident.", progress = "Were you able to retrieve any of my old co-worker's Miners' Union Cards?", completion = "Thank you for collecting these, {name}.  Your efforts will help bring peace to the dead in the wake of this tragedy.  I will see to it that the families are notified.", objectives = "Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[169] = { id = 169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Gath'Ilzogg", description = "Wanted! Gath'Ilzogg, Leader of the Blackrock attacks on Stonewatch Keep and raids against the township of Lakeshire. \n\nGath'Ilzogg is extremely dangerous.  He is reportedly holed up in the recently conquered keep plotting the Blackrock clan's further crimes against humanity.  The orc infestation must be quelled at all costs.  A gracious reward will be given to whatever brave soul can deliver the head of Gath'Ilzogg to Magistrate Solomon.", progress = "What do you have there, {race}?", completion = "Fantastic work, {name}!  Gath'Ilzogg led those brutes into battle, killing many innocent humans.  Vindication is ours.  This is the first step in reclaiming the keep for the kingdom of Stormwind!", objectives = "Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[170] = { id = 170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Threat", description = "I hope you're here to lend us a hand, {class}. After the last trogg attack, we could use all the help we can get.\n\nI hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception. They've been spotted all over the hills to the southeast and near the frozen lake.\n\nAnd that's not all, just a few nights ago, they attacked and overran our camp to the west! \n\nWe're a bit shorthanded here, <lad/lass>, and we need strong arms to help drive the troggs back.", completion = "If the problems we've had here are indicative of what is happening elsewhere in our lands, by Magni's beard, we have some troubles ahead of us! I can only hope that the king and Senate are taking steps to deal with the threat the troggs pose.", objectives = "Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[171] = { id = 171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Warden of the Alliance", description = "You have been so very kind to me, {name}.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.\n\nI wish all the orphans were lucky enough to get to do the stuff we did. Do you think we could find Craggle Wobbletop again and get a foam sword rack from him? I think he's still pushing that cart in the Canals outside the Trade District. That way, everyone else at the orphanage could do something fun too!\n\nAfter that, it'll be time for me to go home.", progress = "It is a pleasure to see you again, {name}.  Have you attended to the duties you've volunteered for during Children's Week?", completion = "What's this? A gift for all the orphans!\n\nMay the heavens bless you, {name}.  You've done more for Randis than most would ever think of doing for him.  Thank you - you're a shining star in the skies of the Alliance.\n\nRandis had so much fun with you, {name}.  He wanted to give you one of his favorite pets to remember him by.", objectives = "Purchase a Foam Sword Rack from Craggle Wobbletop and then return your ward to the Stormwind orphanage by speaking to Orphan Matron Nightingale in the Cathedral District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[172] = { id = 172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children's Week", description = "You're willing to help us here at the orphanage?  Bless you, friend; your aid during Children's Week will be invaluable.\n\nTake this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children's Week itself.  When you use it, you will be able to talk with the child you've agreed to look after.  Using it again will dismiss the child.\n\nBy all means {name} - use the whistle and meet your ward!  I'm sure the child will be most eager to meet you.", completion = "Zug zug!  My name is Grunth, and I guess you're looking after me?  You're an adventurer, like my mom and dad were.  My matron says that they died with honor in battle.  I'm happy to meet you.\n\nI hope we'll do plenty of things together.  I have some things I'd like to do, and the matron says you'll be like a big brother to me during this week.  I'd like that a whole bunch.", objectives = "Use the Orcish Orphan Whistle to talk with the child you will be looking after during Children's Week.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[173] = { id = 173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in the Woods", description = "Darkness seems drawn inexorably to Duskwood. Master Carevin's quest is the expulsion of evil and heresy. Through our efforts are the people of Darkshire kept safe.\n\nYou believe yourself worthy to join us?\n\nI once thought as you. Disillusioned by the complacency of the Watch, I joined Master Carevin. If you wish to prove yourself, it will not be through words.\n\nTest your skills against the Nightbane Shadow Weaver worgen in Brightwood Grove--bright, hah!--and the Rotting Orchard.", completion = "Impressive, {name}. It would seem that you are capable enough to handle yourself. Perhaps a more suitable challenge could be found for one of your abilities.\n\nIt is curious though... The worgen seemed to just appear out of thin air. But then, with all the other strange creatures that have moved across our borders, I suppose it's only one of many concerns.", objectives = "Kill 6 Nightbane Shadow Weaver worgen for Calor in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[174] = { id = 174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ook To The Stars", description = "My Gnomish friend, Cog, has promised to help me build a device which will let me peer towards the stars.  A truth exists, beyond magic, that can explain the strange transformation in the forest.\n\nBring to me a bronze tube made by a skilled engineer.  That is the first step, according to Cog's blueprint.", progress = "Have you found a skilled engineer to create a bronze tube yet?", completion = "This is perfect, {name}.  The first step is complete!", objectives = "Viktori Prism'Antras of Darkshire wants you to bring him a bronze tube.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[175] = { id = 175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ook To The Stars", description = "According to Cog's blueprint, what I need now is a way to reflect light.  I remember a woman by the name of Mary who became well known around these parts for always carrying a looking glass.  Perhaps you can track Mary down and see if she might lend us a reflective surface for this project?  I believe she once resided in southern Duskwood. . .", completion = "Why yes, I used to own a looking glass.", objectives = "Locate Mary and persuade her to give up a reflective surface for Viktori's project.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[176] = { id = 176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: \"Hogger\"", description = "Wanted: Hogger\n\nA huge gnoll, Hogger, is prowling the woods in southwestern Elwynn.  He has overpowered all attempts at his capture.\n\nThe Stormwind Army has placed a generous bounty on the Gnoll.  To earn the reward, bounty hunters should venture into the woods and deal with the beast.", completion = "He did WHAT?\n\n Great, now we have a bloodthirsty beast right beneath the streets of Stormwind, with a whole army of gnolls at his command.  Definitely an improvement, I feel safer already. \n\n Here's your reward, {name}.  But promise me you'll check in with the Stockades guards in Stormwind at some point, just to ensure that things are going smoothly.", objectives = "Deal with \"The Hogger Situation\" and return to Marshal Dughan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[177] = { id = 177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ook To The Stars", description = "The looking glass was one of my finest treasures until. . .the incident.  After that happened, I discarded it behind the barn.  There was an Insane Ghoul who used to roam back there.  Perhaps he picked it up.  Rumor has it the devilish beast resides in the Tranquil Gardens Cemetery.", progress = "I showed Cog the beginnings of our star-viewing machine.  He was impressed.  Did you happen to find a reflective device?", completion = "Most superb!  This will work perfectly.  Many thanks!", objectives = "Retrieve Blind Mary's Looking Glass from the Insane Ghoul and give it to Viktori in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[178] = { id = 178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theocritus' Retrieval", description = "<You hear a disembodied voice...>\n\nDo not be alarmed.  I am Theocritus, High Mage of Tower Azora in Elwynn Forest.  The pendant you are holding is a method of communication between the Shadowhide Gnolls and their master, Morganth.\n\nThrough months of research, I believe I too can communicate through these pendants.  If you can hear this message, then my spell was a success.\n\nBring me this pendant and I will reward you for the service.", progress = "I spoke to you through a pendant, you say?  Hmm...give it to me, so that I might study it.", completion = "You have my gratitude, {name}.  I sent that message to the Shadowhide Pendants weeks ago and had believed it a failure.  But it seems the spell did reach at least some pendants, after a significant delay.\n\nIn time I hope to learn how to send an attack through the pendants, to immobilize any Shadowhide Gnolls who wear them.\n\nBut before that is possible, I'm afraid that much more research is required.", objectives = "Bring the Faded Shadowhide Pendant to Theocritus the Mage at the Tower of Azora in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[179] = { id = 179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dwarven Outfitters", description = "What do we have here? You look as though you might need something to keep your hands warm, hm?\n\nI'll tell you what would help: a pair of nice, warm gloves. And, being the kind soul that I am, I'd be more than happy to provide you with a suitable pair. I've one condition, however.\n\nI need you to go get me some wolf meat. Nice arrangement, hm? You bring me some wolf meat, and I'll make sure you don't lose any digits to frostbite. Well, what do you say?", progress = "Wolves giving you a bit of trouble? You'd do well to avoid the fangs and claws and other sharp bits, yes?", completion = "Ah! Wonderful. The wolf meat should do nicely. Oh, don't worry, {name}, I wouldn't forget my part of the bargain. Here, one of these should fit you.", objectives = "Sten Stoutarm would like 8 pieces of Tough Wolf Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[180] = { id = 180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Lieutenant Fangore", description = "Wanted: Lieutenant Fangore\n\nKnown leader of the Shadowhide Gnoll Clan, working under the enemy of the Township and Kingdom, Morganth.  By mandate of Magistrate Solomon, this vile betrayer of Stormwind is wanted dead.  Show his paw to the Magistrate as proof of his death.", progress = "What news do you bring before the Court?", completion = "So the evil Lieutenant Fangore is dead?  Good riddance to that foul creature.  You are very brave, {class}.  The Township of Lakeshire thanks you for your aid.", objectives = "Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[181] = { id = 181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ook To The Stars", description = "Now there is just one more item needed to complete this device.  Cog's blueprint calls for a lens of some sort.  The only lens I know of that would be large enough will be very difficult to acquire.\n\nThere is an ogre by the name of Zzarc'Vul who resides in the mound in southern Duskwood.  If you can, bring to me his monocle and I will use that as our lens!", progress = "Were you able to convince Zzarc'Vul to lend us his monocle for our experiment?", completion = "At last!  The stargazing device is complete!  Thank you, {name}.  Now I can continue my research. . .", objectives = "Locate Zzarc'Vul in the southern ogre mound in Duskwood and return his monocle to Viktori in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[182] = { id = 182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Troll Menace", description = "The trolls're acting up.  More than usual, I'd say.  We've seen them put together war parties before, but this time it's... different.\n\nWhat matters most, however, is the continued protection of Anvilmar.  I've no intention to let these trolls flank Anvilmar while its attention is turned towards troggs.  Go thin their ranks a bit.  They need to know that we're still not without defenses.", completion = "Hopefully that did the trick.  Anvilmar will be safe from trolls for the time being.  Now, to find out what it is that has the trolls so agitated.", objectives = "Kill 10 Frostmane Troll Whelps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[183] = { id = 183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Boar Hunter", description = "Nothing like a day of boar hunting, eh?\n\nThough, here in Coldridge Valley, there are so many boars it almost takes the fun out of it. No need to get them charging. They're all angry and ready without any help. In fact, recently, there've been so many boars in the area, it's become dangerous for me to do my daily hunting.\n\nLong story short, if you could help me kill some of the boars, I would appreciate it.", completion = "Excellent! I can go back to my... leisurely... hunting now. Thank you, {name}.", objectives = "Talin Keeneye would like you to kill 12 Small Crag Boars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[184] = { id = 184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furlbrow's Deed", description = "This is an old deed to an expanse of farmlands within Westfall.  It is signed by a Theodore Furlbrow and cosigned by his wife, Verna.  And on the back of the deed are hastily scrawled words:\n\n\"We leaned on Furlbrow and got his deed.  Thought it might be handy if you wanted to forge one of these for your own place.\n\nThe Furlbrows won't give us trouble.  Last I saw them they were on their way out of Westfall, stuck with a broken wagon.\"\n\nYou think the Furlbrows might want their deed back...", progress = "We don't need any civilian vigilante types getting involved, kid. Leave this one to the professionals.", completion = "This is useless. Look at the date on this letter. The Furlbrows have been squatting on the Jansen Stead for five years.\n\nThey never could quite get their wagon... fixed.", objectives = "Bring Furlbrow's Deed to the Jansen Stead in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[185] = { id = 185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Hunting", description = "When I was but a young girl, my father trained me in the art of tiger hunting.\n\nYou'll find the young felines much easier to track and slay.  One can often find young tigers near the expedition camp.\n\nTest your tracking skills and see if you can hunt some of the beasts down.  Start your hunt near our camp, to the south.", completion = "You have finished with the young tigers... but the thrill of the hunt still holds you captive.", objectives = "Hunt 10 Young Stranglethorn Tigers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[186] = { id = 186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Stalking", description = "Young tigers are one thing.  Fully-grown cats are another.  Hunting the grown Stranglethorn tigers will prove an even greater challenge.\n\nThe adult cats normally spend their days south of Kurzen's Compound, east of the river.", completion = "Tiger blood coats your hands, your weapons, and your {class} garb.  Yet still you crave more.", objectives = "Hunt 10 Stranglethorn Tigers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[187] = { id = 187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Prowess", description = "Elder Stranglethorn tigers are the strongest of the bunch.  More than one {race} {class} has seen <his/her> own demise at the tip of those razor-sharp teeth and heavy claws.\n\nAjeck will be thrilled to know that you have bested them.  The largest pack of these elders can be found to the south, near the Sundering, on the border of the Cape of Stranglethorn.", completion = "You have defeated the strongest tigers in Stranglethorn.  You have become a great tiger hunter, and have every right to stop your hunt right here and now.\n\nSomething tells you, however, that a stronger cat still waits for you within that jungle...", objectives = "Hunt 5 Elder Stranglethorn Tigers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[188] = { id = 188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Mastery", description = "Legends speak of an elusive tigress... a feline so powerful that she dwarfs even the elder males.  The hunters at Nesingwary's Expedition have hunted for her without success.  Many of them have fallen prey to her raking claws, their bodies now decaying at the foot of her hill, north of Grom'gol.\n\nThey call the beast Sin'Dall.\n\nYou resolve to do what no {race} has done before: hunt, kill, and claim the paw of Sin'Dall.", progress = "How goes the hunt?", completion = "Most impressive, I do say!  I send you out to defeat the kittens, and you return with a paw the size of a gnome!  You are a true Master Tiger Hunter, {name}!", objectives = "Hunt Sin'Dall and return with her paw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[189] = { id = 189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodscalp Ears", description = "Damn trolls! They've been killing off our agents in the jungle! I've already lost a good number of my best guards to skirmishes with them. The costs are piling up! How will I explain this to Baron Revilgaz?\n\nDecisive action... Think, Kebok... you weren't assigned to the post you have today for sitting around... I've got it! You... {name}, is it? You'll help me, won't you? There's money to be had!\n\nHere's the deal... you bring me the ears of fifteen Bloodscalp Trolls, and I'll compensate you well.", progress = "You've had success I hope? All over the place, those trolls. Filthy devils.\n\nOh yes, that reminds me! Be sure to tell your friends, yes? We could use much assistance!", completion = "Oh excellent, excellent. That'll help a little, for the present...\n\n<He trails off, grumbling about profit margins and costs...>\n\nWhat? You're still here? Reward? Oh, right... of course, here, take this... it should be more than enough.", objectives = "Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[190] = { id = 190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panther Hunting", description = "If you want to be a part of the hunt with this crack group under Hemet Jr.'s leadership, you're going to need to prove yourself an able panther hunter.  You should start out easy: just focus on the young panthers for now.  As you improve and gain experience as a hunter, you will undoubtedly find increasingly dangerous quarry.\n\nStart by heading east.  Return to me when you are a master panther hunter.", completion = "You feel more experienced already.  Perhaps it's time to move on to bigger prey.", objectives = "Hunt 10 Young Panthers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[191] = { id = 191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panther Stalking", description = "The youngest panthers fell easily before you.  panthers that have come of age will naturally be stronger, and quicker, and more difficult to defeat.\n\nLarger panther tracks lead to the west.", completion = "You take a moment to silently congratulate yourself on your panther hunting so far.", objectives = "Hunt 10 Panthers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[192] = { id = 192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panther Prowess", description = "Now the hard part.  As panthers grow older, they become more wily, blending in with their environment and becoming difficult to spot.  These cunning panthers are known by the name \"shadowmaw\", for their tendency to suddenly appear out of the darkness... with a waiting mouth full of teeth.\n\nIf you want to prove yourself as a true panther hunter, shadowmaws are the only way to do so.  They prowl to the southeast, across the river.", completion = "The shadowmaw panthers proved no match for your skills as a hunter.  Only one task remains.", objectives = "Hunt 5 Shadowmaw Panthers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[193] = { id = 193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panther Mastery", description = "You've almost proven yourself to be a master hunter of panthers.  Yet there is one panther which has eluded your grasp.\n\nSongs are sung about a mighty panther by the name of Bhag'thera.  You will see if you can use your skills to kill the great beast.\n\nBringing the Fang of Bhag'thera to Erlgadin should be proof enough that you are a master panther hunter.", progress = "You're still alive!  Excellent!  How fares the hunt?", completion = "So the great Bhag'thera is dead!  Cheers to you, {name}.  You are a mighty {class} indeed!", objectives = "Obtain the Fang of Bhag'thera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[194] = { id = 194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Hunting", description = "So you think your hunting skills are in tip-top shape?  I can put them to the test in a jiffy.  Head out into that jungle and kill ten Stranglethorn raptors.  We'll see just how much of a big game hunter you are.\n\nAnd no, I won't tell you where you can find them!  Locating the beasts is half the challenge.\n\nOkay, go west.", completion = "Stranglethorn raptors were not a problem for a wily {class} like you.", objectives = "Hunt 10 Stranglethorn Raptors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[195] = { id = 195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Stalking", description = "It is time to step up the challenge.  Venturing into the jungle and bagging 10 lashtail raptors should be sufficient.  They will certainly be stronger than the raptors you have already disposed of.\n\nThe lashtail raptors mainly stay southeast of here, near the Kal'ai Ruins.", completion = "Hemet Nesingwary Jr. doubted you, but his doubts were unfounded.  You are absolutely destroying these raptors.", objectives = "Hunt 10 Lashtail Raptors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[196] = { id = 196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Prowess", description = "A particularly cagey brand of raptor, known by locals as the \"Jungle Stalker\", prowls the forests to the south, across the river.  They are far more difficult to track down and kill than the other breeds you've been trying your luck at.\n\nKilling these Jungle Stalkers will undoubtedly make for a good tale around the fire.", completion = "You are no longer just a raptor hunter.  You are an honest-to-goodness raptor SLAYER.\n\nThough one fabled raptor still eludes you...", objectives = "Hunt 10 Jungle Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[197] = { id = 197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Mastery", description = "Before returning to Nesingwary's Expedition, you will have to complete the impossible: hunt the raptor that no other hunter has been able to capture.  That beast goes by the name of Tethis, and he's been known to terrorize the southeastern corner of Northern Stranglethorn.\n\nBringing Tethis' talon back to that dwarf hunter should be proof that you are no ordinary {race}.", progress = "Ah, so you're hunting Tethis?  Tracked her all the way back to camp, did you?", completion = "Master {name}, the raptor slayer!\n\nHas a nice ring to it, eh?", objectives = "Hunt Tethis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[198] = { id = 198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies to Private Thorsen", description = "Hmm. Yes, I do have something you could do, actually. Lieutenant Doren and his followers up in the north need their regular supplies from us.\n\nThey haven't been delivered, and with the trolls attacking, I'll need someone to do it. Doren's camp lies northwest of the road at the entrance to Stranglethorn from Duskwood. Give the supplies to Private Thorsen, if he's not in the camp, then he'll be patrolling south of it. He'll take care of them.\n\nMind you, if you fail, you'll owe me restitution.", progress = "Yes? What do you want? Oh, supplies from the goblins. Strange seeing a {race} delivering them, usually they send their own. No matter... you didn't touch them did you? Good good... we wouldn't want anything to happen to our mines, oh no.", completion = "These land mines will help us defend ourselves from that animal Kurzen and his men. Thank you for bringing them. If you need further work, I can probably find something for you to do. And you won't have to deal with those goblins, hm?", objectives = "Deliver the Miscellaneous Goblin Supplies to Private Thorsen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[199] = { id = 199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Threat Looms", description = "You take a sample of the strange smelling powder.", progress = "Did you happen to discover any clues, {name}?", completion = "This is an alarming discovery, to say the least!", objectives = "Return to Chief Engineer Hinderweir and show him the clue that you discovered.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[200] = { id = 200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bookie Herod", description = "If Kurzen knows Thorsen's secret, then we have a spy in our midst.  We must determine how the secret was leaked!\n\nThorsen's contact within Kurzen's camp was Bookie Herod.  Herod is Kurzen's logistics officer and knows everything about the running of Kurzen's Compound.  If you can get Herod's notes or records, maybe we can find out how Thorsen was discovered.\n\nWhen we were still with Kurzen, Bookie's office was on the top floor of the camp's only two-story house.  His records are probably still there.", completion = "These are Bookie Herod's notes and records.\n\nAmong them are: a list of supplies within the camp, material requests from Colonel Kurzen, and various letters and correspondences.", objectives = "Find Bookie Herod's Records.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[201] = { id = 201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Camp", description = "I've gotten reports of a group of hunters that have set up camp upriver of the Venture Company mining camp on Lake Nazferiti.  Now, normally I wouldn't care, but improbably, I heard that Hemet Nesingwary Jr. was one of the hunters there.  He's certainly well-connected, if you catch my meaning, and you never can be too safe.\n\nWhy don't you go check out the camp, {name}, see what they're about?", completion = "Hmmm, so my information was correct, as usual.  Interesting.  Well, I don't suppose they pose any sort of threat of interference with our operation, but perhaps they have a need for some of our excellent manufactured products.  Hmmm...", objectives = "Find the hunters' camp and report its location to Krazek in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[202] = { id = 202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Colonel Kurzen", description = "You have proven yourself time and again, and your resourcefulness seems to rival even that of Kurzen himself.  You may be the salvation of our band of rebels...if you can pit yourself against Kurzen and prevail!\n\nHe commands his men from deep within the Stockpile.  You must enter that cave, brave through his defenders, and face Kurzen and his leaders.\n\nFarewell, {name}.  My hope, and the fate of my men, go with you.", progress = "Dare I hope that Kurzen and his defenders are dead, {name}?", completion = "I dared not believe the reports, but you bring us proof that...Kurzen and his leaders are defeated.  You have saved us!\n\nThese jungles are filled with menaces of all types, but none had the cruel intellect of Kurzen.  We may all breathe easier now that he is gone.", objectives = "Kill 6 Kurzen Elite, 4 Kurzen Subchiefs, and bring Kurzen's Head to Lieutenant Doren at the Rebel Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[203] = { id = 203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Rebellion", description = "We're fighting a losing battle with Colonel Kurzen.  Not only is he a brilliant tactician, he outnumbers us at least 10 to 1!  To survive, we need to use his own, covert tactics against him.\n\nEnter his camp to the east and kill his men.  Lots of them.  And get out before reinforcements can close on you.", completion = "Well done.  The loss of those Jungle Fighters will relieve some of the pressure on our camp.\n\nBut now that you've had a taste of the forces we're up against, do you still want to throw your lot in with us??", objectives = "Kill 15 Kurzen Jungle Fighters.\n\nReturn to Sergeant Yohwa at the Rebel Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[204] = { id = 204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Medicine", description = "To have a chance against Kurzen, we need his healing support neutralized.  He has gathered a large number of medicine men who heal his forces with jungle remedies and poison our fighters with venom fern extracts.\n\nWe need those remedies and extracts for our own.  Search the Kurzen Compound - his medicine men and jungle fighters will have the remedies, and the extracts are probably stowed in some of the camp's supply boxes.", progress = "I'm waiting on those remedies and that extract, {name}.", completion = "Well done, {name}.  These remedies will keep more of us alive and in fighting shape.  And the extracts will help us create our own remedies.", objectives = "Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[205] = { id = 205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Witchery", description = "While I study those legends you acquired, gather for me implements of evil troll magic.  Enter the territory of the Skullsplitter trolls, a second tribe to the distant south, and acquire Skullsplitter Fetishes from their Witchdoctors and Mystics.", progress = "Do you have those fetishes, {name}?  They might hold the secret to Kurzen's degradation...I must know!", completion = "Thank you.  I will study these fetishes and see if they hold the secret of Kurzen's fall into evil.", objectives = "Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[206] = { id = 206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mai'Zoth", description = "Kurzen may be dead, but...that which drove him to evil still lives!  Through my studies I have discovered this: An Ogre Mage - Mai'Zoth - dwells in an Ogre Mound within the eastern mountains of Stranglethorn.  He is rumored to employ mind-controlling magic, and I am positive that he corrupted Kurzen.\n\nIf Mai'Zoth is allowed to live, then his evil may influence others, and may even cause another Kurzen to surface.\n\nKill him, and bring me his Mind's Eye, the artifact he uses to corrupt others.", progress = "I give you my blessing.  Mai'Zoth's strength is matched only by his evil.", completion = "Aha!  You've done it!  You are a great force for good, {name}, and may your strength never fade!\n\nI will study this Mind's Eye and determine if it may be used for good.  If not...then it must be destroyed.", objectives = "Bring the Mind's Eye to Brother Nimetz at the Rebel Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[207] = { id = 207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurzen's Mystery", description = "Colonel Kurzen was once a great, noble man - I must find what caused his fall into depravity!  He may be under the sway of troll magic.  To confirm this, I must study some of their legends.\n\nThere are 4 tablets hidden within the troll ruins of Stranglethorn.  I must see what is written on these tablets!  Transcribe their markings and bring the transcriptions back to me.\n\nThe first tablet is in the Bal'lal Ruins, the second is in the Vile Reef, and the third and fourth are in the Ruins of Zul'Kunda.", progress = "{name}!  Do you have the troll legends?  I must know their secrets!", completion = "Thank you, {name}.  I will study these legends to see if there is some link between the trolls and the evil that has possessed Colonel Kurzen.", objectives = "Find the 4 tablets and bring their legends back to Brother Nimetz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[208] = { id = 208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Game Hunter", description = "{name}, you are a hunter worthy of our company.  From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated.\n\nYou have killed the ferocious Sin'Dall, the elusive Bhag'thera, and the treacherous Tethis.  But the true prize is the head of King Bangalash.  That white tiger is the reason I am here... yet still, he taunts me from his roost to the south.  Kill King Bangalash and your hunting prowess is proven to be second to none.", progress = "I see you're back, old bloke.  King Bangalash has caused me to come crawling back to camp many times.  Hang in there.", completion = "Bloody well done!  Right-o!  Congratulations, {name}, for succeeding where others have failed.\n\nI am honored to count you as a comrade of our great hunting party here.  No one will ever doubt your expertise in hunting and tracking!\n\nCheers to you, I say!  Cheers!", objectives = "Hunt for the head of King Bangalash, the great white tiger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[209] = { id = 209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skullsplitter Tusks", description = "It's expensive and hard to kill enough tigers to support the export of tiger fangs to the islands in the South Seas. Luckily, we've developed a technique that allows us to take mundane horn-like objects and turn them into undetectable forgeries.\n\nThe closest match we've found, amazingly, are the tusks of the Skullsplitter trolls.\n\nHey, before you say anything, what the buyer doesn't know doesn't hurt them, am I right? Bring me a large number of them so we can get to work on the monthly shipment!", progress = "Tough buggers, aren't they? Well, have you had any luck? Sorry to seem impatient, but this has been a huge thorn in my side! Well?", completion = "Ah, good work, good work! Ugh, though you could have done a better job cleaning off the-- Well, no matter, no matter! My thanks to you, {name}, our operation will no doubt see increased output and productivity thanks to your help! Good good, now, onto other matters...", objectives = "Acquire 18 Skullsplitter Tusks and return them to Kebok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[210] = { id = 210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krazek's Cookery", description = "I do most of the cooking at the camp.  And it used to be a lot of work, until I bought a mechanical cooking pot from a goblin merchant in Booty Bay.  The pot is a wonder!  It saved me countless hours...until it broke!\n\nCan you take the pot back to the goblin for me so he can fix it?  His name is Krazek.", progress = "Hello!  You brought me something?", completion = "Oh I see, it's a Krazek's Crock Pot!  An ingenious piece of work, but it can break a spring or throw a gear now and then.  Let me see what's wrong with this one...\n\nAha!  Its steam charger is rusted out, it has a cracked knuckle-gasket and its fobulator is missing teeth.  I'm surprised the pot could even boil a turnip in this state!\n\nCan I fix it?  Of course I can fix it!\n\nBut there's a price.  Oh yes, there is always a price...", objectives = "Bring Krazek's Crock Pot to Krazek the goblin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[211] = { id = 211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alas, Andorhal", description = "Alas, the time to attack Andorhal and drive out the lich that controls it is upon us!\n\nInside the ruins of the city is where the lich - Araj the Summoner - holds dominion.  He is guarded by numerous Scourge surrounding the remains of city's center, and his personal retinue of guardians attached to him directly is formidable.  You will need numerous allies to even stand a chance of facing him successfully.\n\nDestroy Araj, {name}, and bring me a shard from his phylactery as proof!", progress = "Your task has been given to you, {name}.  Do you have a shard from the lich's phylactery as proof of the task being accomplished?", completion = "You've done it!  Araj... the lich is finally defeated!\n\nYou've done a tremendous service to the Alliance on this day, {name}.  Your bravery and perseverance are a testament to what it means to be a true hero.  Please - accept this as a token for all to see and know that you have delivered the Alliance a victory for the ages!", objectives = "Bring Araj's Phylactery Shard to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[212] = { id = 212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Meal Served Cold", description = "One of my most famous dishes is Chilled Basilisk in Lime Vinaigrette.  But the problem is... the meat is impossible to keep fresh, and I must serve the dish tonight for a noble's birthday!\n\nSo if you can bring me a Chilled Basilisk Haunch from a freshly-killed Cold Eye Basilisk, quickly, then I will owe you a king's feast!\n\nCold Eye Basilisks are known to roam along the beach dunes of northwestern Stranglethorn, so you have much traveling to do.  And be swift!", progress = "{name}!  Do you have that haunch?  I must begin preparing it soon, or the banquet will be ruined!", completion = "Ah, this will do nicely!  Many, many thanks!\n\nNow if you'll excuse me, I must get the haunch chopped, marinated and garnished for the banquet.", objectives = "Kill a Cold Eye Basilisk, get a Chilled Basilisk Haunch, and return it to Angus Stern in the Blue Recluse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[213] = { id = 213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostile Takeover", description = "He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!\n\nRevilgaz won't have it, and he's told me to take care of the problem in my own way.\n\nMy way? Theft. The Venture Co. geologists near Lake Nazferiti are deeply interested in those strange blue crystals they have been finding in the mines. Bring me samples of the stone from their geologists, I don't care what you have to do to get them.", progress = "I need those stones, {name}. By whatever means necessary! Just do it, don't give me the details!\n\nIt's about results, {name}, nothing more, nothing less.", completion = "Fascinating. That the crystals have been tumbled using this process can only indicate that they are planning to use them as some sort of fuel or other catalyst. I don't know much more than that. Samples will have to be dispatched to Head Chemist Gigglefont.", objectives = "Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[214] = { id = 214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red Silk Bandanas", description = "It's no secret that the trademark of the Defias Gang is their Red Bandanas.  But we've learned that the material from which these bandanas are made signifies the member's rank.\n\nThat being said, I want you to eliminate as many high ranking Defias members as you can.  The highest ranking members will undoubtedly be found in VanCleef's secret hideout.  When you're done bring me 10 Red Silk Bandanas as proof of their deaths and I will reward you.  Good luck, {name}.", progress = "Have you been reclaiming our land from the Defias gang?  If so show me 10 Red Silk Bandanas as proof.", completion = "Well done, {name}!  On behalf of The People's Militia I salute you for your efforts.  Soon we will return this land to the people with help from brave souls like you.", objectives = "Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[215] = { id = 215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jungle Secrets", description = "Thank you for saving me, {name}.  I know how this looks, but...allow me to explain.\n\nI was charged by Lieutenant Doren to re-enlist with Kurzen's men, so that I might spy on them and bring sorely needed intelligence to the rebels.  You saw here what I had thought would be my chance to infiltrate Kurzen's Compound.  I was wrong, and again, thanks for saving me.\n\nThis was a top secret mission, so you must tell no one.  But if you speak with Doren he will explain.", completion = "Yes, what Thorsen told you is true.  You must be discrete with this.  At one time, we rebels were fiercely loyal to Colonel Kurzen.  But such was Kurzen's corruption, our passion twisted into rage.   If it was made known that Private Thorsen has had recent dealings with Kurzen's men, then one night he would find himself with a slit throat.\n\nTo my knowledge, only Sergeant Yohwa, Thorsen and I were privy to Thorsen's mission.  But there must be another.  A traitor.", objectives = "Speak with Lieutenant Doren at the Rebel Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[216] = { id = 216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between a Rock and a Thistlefur", description = "The Thistlefur furbolgs are threatening our expansion!  Thistlefur Village to our west blocks the way between us here and the Splintertree Post.  It's a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path.\n\n{name}, we must not allow... an expansion path gap!\n\nProceed to Thistlefur Village and thin out the furbolgs.  You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!", completion = "Well done {class}, well done!  I will continue to send forces to thin out the furbolg, but I can at least count on a different path that will be free of Alliance entanglements.  The Horde conquest of Ashenvale is now in full swing!\n\nYou've earned your pay this day, hero.  I salute you!", objectives = "Karang Amakkar at Hellscream's Watch wants you to take down any 15 Thistlefur furbolg in Thistlefur Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[217] = { id = 217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Decisive Strike", description = "My ploy worked. It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug. Grawmug is heavily guarded, however. Two of his most elite guards, Gnasher and Brawler, never leave his side.\n\nIf you feel yourself worthy, {name}, I want you to lead the assassination mission on Grawmug and his two thugs inside this cave. Go! I'll free myself from these bindings and meet you shortly.", completion = "Most excellent, {name}!  You have brought hope to Loch Modan.  With Grawmug dead, we stand a better chance of seeing the Troggs eliminated from the land.", objectives = "Kill the trogg leader, Grawmug, and his two guards, Gnasher and Brawler, and then report back to Captain Rugelfuss in Thelsamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[218] = { id = 218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice and Fire", description = "Soren did well to send you out on recon.  That's some good information you have right there.\n\nTrouble is, this just adds more work for us to do.  The trolls, confused as they are right now, still would like to kick the dwarves right out of Coldridge.  And I'm certainly not going to let some fiery demon turn our snowy valley into a mountain lake.\n\nThe troll leader, his servants, and the fire creature should all be in the cave to the southeast.  Take 'em all out.", progress = "{name}! Any luck?", completion = "I'm glad you've returned safely, {name}.  While it may not look like it now, you've proven to be a tremendous asset in the protection of Anvilmar.\n\nHere, take this as a symbol of my gratitude.", objectives = "Kill Grik'nir the Cold, 6 Frostmane Blades, 3 Frostmane Novices, and the Wayward Fire Elemental.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[219] = { id = 219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing In Action", description = "At last, friends of the Alliance!\n\nHelp... please... \n\nThe last thing I remember these foul Orcs overpowered our regiment.  Most the men were killed. I took a strong blow to the head and everything went black. Now I am held captive in this cave.  Help me, I am hurt badly.\n\nI'll need help getting back to town... please... you're my last hope...", completion = "You have served the Kingdom well, {class}.  Thank you for assisting Corporal Keeshan with his escape from those dreaded Blackrock Orcs.  You shall be rewarded for your brave acts this day.", objectives = "Protect Corporal Keeshan on the journey back to Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[220] = { id = 220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Islen will have one more task for you before rewarding you with your next totem. The vial of water I've given you is necessary for whatever that task is.\n\nGo now and find her. We shall meet again some day.", objectives = "Bring the Vial of Purest Water to Islen Waterseer at the Tidus Stair in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[221] = { id = 221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in the Woods", description = "You might have noticed some larger worgen wandering around with the Shadow Weavers in the woods? From what we can tell, these Dark Runners make up the bulk of the worgen numbers.\n\nOn my rangings, I've also noticed that they have overrun the Rotting Orchard southwest of town. These worgen are a bit tougher than the last you faced.\n\nBe on your guard.", completion = "You performed well against the Dark Runners, {name}. But it seems as though their numbers are inexhaustible. Every time we make progress, more spring up to refill their ranks.\n\nWhat is the evil power that draws them here? Why have they come to disturb our unhappy realm...\n\nI will put my faith in Master Carevin. No doubt he will get to the bottom of the problem.", objectives = "Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[222] = { id = 222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in the Woods", description = "Your previous accomplishments have convinced me that you are ready to take on the toughest worgen infesting the woods.\n\nOf the worgen that have made their new home here, the Vile Fangs and the Tainted Ones have proven the most dangerous. They've settled down near some of the caves and in the mine to the south.\n\nFrom far away you can even see the light from their bonfires...", completion = "{name}, to be honest with you, I did not believe that you would get this far, but you are clearly a {class} to be reckoned with. In fact, if you wish to formally join Master Carevin's struggle, I will gladly write for you a letter of recommendation.", objectives = "Kill 8 Nightbane Vile Fang and 8 Nightbane Tainted One worgen for Calor in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[223] = { id = 223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in the Woods", description = "Here you go, {name}. Bring this message to Master Carevin.\n\n<He quickly removes a piece of faded parchment and offers it to you.>\n\nA few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today.", progress = "Yes, what is it? Make it quick, I've pressing matters to attend to.", completion = "Excuse me for my cold reception, {name}, but as I'm sure you can tell, I am an extremely busy man. I see that you have impressed Calor--and I assure you, that is no small feat--and that he has given his recommendation.\n\nThere are unsavory types afoot, {name}, and we can use the help of all who have proven themselves. We battle against demons, the undead, and those who would provide them aid. Be vigilant, be wary, and trust none who would not give aid to our cause.\n\nGlory under the Light.", objectives = "Bring Calor's note to Jonathan Carevin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[224] = { id = 224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of the King's Lands", description = "We need to protect the Loch, {name}! With so many of the King's soldiers fighting valiantly on remote battlefields, we've become overwhelmed on the home front. Troggs are tunneling up from every crevice! The Trogg infestation poses the largest threat to Ironforge.\n\nWe need you, brave adventurer, to venture forth and lay waste to the Trogg threat. Slay 6 Stonesplinter Troggs and 6 Stonesplinter Scouts and report back. You will find most of the vermin through the passes into the mountains to the south.", completion = "Well done, {name}!  You demonstrated uncanny courage on the battlefield.  Our war against the Troggs will be won with efforts such as yours.  You have served King Magni well.\n\nIf you fancy yourself well-suited for this kind of adventuring, I suggest you speak with Mountaineer Gravelgaw.  The Captain has him assigned to a rough patrol that I am sure he can use some help with.  Check with Gravelgaw just inside the tower.", objectives = "Mountaineer Cobbleflint at Thelsamar wants you to kill 6 Stonesplinter Troggs and 6 Stonesplinter Scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[225] = { id = 225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weathered Grave", description = "The weathered grave marker reads simply:\n\nMORGAN LADIMORE\n\n<Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>", completion = "Morgan Ladimore?\n\nAhh, yes, of course. His was a long and sorrowful tale. I knew him, well, before he left for the war, but that was the last time I saw him. A noble and good man, he was, but he suffered a bad end.\n\nHere, I should have something here that can tell the tale better than my own recollections...", objectives = "Speak with Sirra Von'Indi in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[226] = { id = 226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolves at Our Heels", description = "Sven and I have dangerous days ahead of us, what with the Necromancer to the east and all.  And out here alone as we are, we have to hunt for our own food.  It seems every time I'm heading back to camp with some meat on me, starving or rabid dire wolves come out of the forest wanting a bite.  It goes without saying, living out here is dangerous work!\n\nBut if you can rid us of some of those wolves, we'd have an easier time of it.  They mostly prowl north and east of here, near the river.", completion = "Oh good.  You thinned out that pack quite a bit, and without those wolves nipping out our heels, we can bind our minds to dealing with Morbent Fel.\n\nHere, take some of these Flash Bundles.  They make them in town, and a lot have been donated to Sven to help with his cause.", objectives = "Kill 12 Starving Dire Wolves and 8 Rabid Dire Wolves, then return to Lars at Sven's Camp on the western border of Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[227] = { id = 227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan Ladimore", description = "<He searches through the shelves and comes up with a leatherbound book.>\n\nIf you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.", completion = "Morgan Ladimore? Never heard of...\n\nOh, you mean Mor'Ladim! I guess you haven't heard the story?\n\nWell, I'll give you the short version. A wandering undead calling itself Mor'Ladim has been wandering Duskwood. From what we've gathered, it appears to be the undead body of Morgan Ladimore, of whom you apparently know. He's been causing us all sorts of problems, attacking Watchmen on patrol and killing people.\n\n<She sizes you up.>\n\nYou seem to be capable enough, maybe you could lay him to rest.", objectives = "Speak with Commander Althea Ebonlocke in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[228] = { id = 228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'Ladim", description = "From what my scouts tell me, Mor'Ladim wanders throughout Duskwood, following a strange and meandering path through the cemetery. We buried him out past the house on the hill, you know where that is?\n\nThere isn't anything I can do to help you, but I wish you good luck.", progress = "I don't blame you if you're having trouble with him, {name}. Some of our strongest Watchers have been lost to Mor'Ladim.", completion = "You killed him? That's no small accomplishment, {name}! On behalf of the people of Darkshire and the Night Watch, I thank you.\n\nAh... there is one small matter, however...", objectives = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[229] = { id = 229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Daughter Who Lived", description = "I should have told you this earlier...\n\nHow do I put this...\n\nMorgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.", sourceObjective = "Speak with Watcher Sarah Ladimore in Darkshire.", completion = "Yes? My father...\n\n<Her eyes become downcast.>\n\nI wish... there was something I could have done for him... If only I had talked to him before he...", sourceObjectiveStatus = "unverified-source-field" }
quests[230] = { id = 230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sven's Camp", description = "Digging through the mound, you find a small, dirt-stained book.\n\nThe book has no title, but...it has information Sven would like to know.", progress = "You found what??  Please, let me see it...", completion = "<Sven reads the book's pages, then slams it shut.>\n\nThat shadowy figure I saw was a witness to my family's death!  There are questions I'd like to ask that man...if only I knew who he was!", objectives = "Bring the Book from Sven's Farm to Sven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[231] = { id = 231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Daughter's Love", description = "Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened.\n\n<There are tears in her eyes now, as she slides a ring from her right hand, and presses it into your hands.>\n\nAnd... thank you, {name}.", progress = "Leave me be...", completion = "<A ghostly voice sounds on the wind...>\n\nThis is...? Sarah? Could it be she's still alive? The weight is removed from my shoulders...\n\n{name}. Take my sword, Archeus. As my soul is put to rest, I have no more need for it. It was forged to do good, and though I have proved myself unworthy to hold it, perhaps you will carry on the Light through it.\n\nLys, my love...", objectives = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[232] = { id = 232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errand for Apothecary Zinge", description = "The Royal Apothecary Society needs your assistance.  Listen closely, and both of us may profit from my plan.\n\nApothecary Keever in the next room may be... touched... but his research does potentially bear fruit if it were pursued by a clever researcher.  Fortunately, I am such a researcher.  I want you to take this purchase order to Alessandro Luca, the proprietor of Blue Moon Odds and Ends; he'll give you a testing kit.  When you have it, bring it back to me and I'll outline your task in detail.", progress = "Yes, and what may I assist you with?  Are you here on business for the Royal Apothecary Society, or have you arrived here merely to brighten my day?", completion = "Ah, Zinge needs a kit, does she?  It saddens me that Zinge does not choose to grace myself with her sweet presence.\n\nVery well, let me procure a kit for you.", objectives = "Take the purchase order to Alessandro Luca in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[233] = { id = 233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldridge Valley Mail Delivery", description = "Hm, I don't suppose you'd be willing to do a favor for me, <lad/lass>? A stack of letters came through the pass today, but I don't have the time to send them along.\n\nThey're all addressed to Talin Keeneye. You can find him to the west down the road. He's set up camp next to the frozen lake.\n\nWhat do you say?", progress = "Yes? Do you have something for me?", completion = "Thank you, I've been waiting for these letters for quite some time...\n\nUnfortunately, these letters aren't all for me. This one is addressed to Grelin Whitebeard. He's not too far away if you'd like to deliver it to him.", objectives = "Deliver the stack of letters to Talin Keeneye in Coldridge Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[234] = { id = 234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldridge Valley Mail Delivery", description = "If I remember correctly, Grelin's camp is down the road to the southeast. No doubt he'll be eager to get his mail.", progress = "Is there something I can help you with?", completion = "Ahh, excellent. It's been a while since I received word from Ironforge.", objectives = "Deliver the letter to Grelin Whitebeard in Coldridge Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[235] = { id = 235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashenvale Hunt", description = "Attention, young adventurers!  The wilds of Ashenvale await you!\n\nThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!", completion = "Welcome to the new frontier, {name}. Ashenvale is a land of opportunity, one where a young {class} like yourself is able to find boundless chances to prove their mettle. Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt. Listen close, and I will gladly share with you what you need to know.", objectives = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[236] = { id = 236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Demolishers", description = "{name}! About time you showed up. While the battle may be over, we still need to prepare for the next battle. Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve several eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolisher and Siege Engines. \n\nOh, and if you happen to see some of the Horde in the Cauldron, don't hesitate to slay them and take their embers. We can't let them have the advantage in the next battle.", progress = "Well? Did you manage to find the embers or did the Horde beat you to it and leave you crying?", completion = "Excellent! This will help fuel the flames of war for days to come.", objectives = "Siege Master Stouthandle at Wintergrasp Fortress wants you to retrieve 10 Eternal Embers from Horde players at the Cauldron of Flames.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[237] = { id = 237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of the King's Lands", description = "Mountaineer Cobbleflint had nothing but good things to say about you, {race}.  For that reason I am going to entrust upon you a mission of utmost importance.  We need to keep pressure on the invading Trogg forces until our Dwarven brethren return from the Alliance front.\n\nSet forth into the southern hills and kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers.  Your attacks will buy us some time.  Report back when your mission is complete.", completion = "You accomplished your mission well, {race}.  The King himself would be proud.\n\nThe reinforcements promised to us never showed, however.  Apparently the Alliance front is a sea of crimson from the blood of our fallen brethren.  The news of the losses leaves a bitter taste in one's mouth.  But we must not let their deaths go for naught.  We must rally in these grim times and bring glory back to the Alliance.\n\nSpeak with Mountaineer Wallbang for reassignment.  You're needed now more than ever.", objectives = "Mountaineer Gravelgaw in the southern guard tower wants you to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers and report back to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[238] = { id = 238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errand for Apothecary Zinge", description = "The kit is ready, {name}.  No doubt that Apothecary Zinge will want this as soon as possible.  Take it to her without delay, and let her know that I will add the cost of the kit to the Society's tab.  Also, please extend to her my warmest salutations.\n\nWell, don't just stand there.  Such is the life of a simple courier, yes?", progress = "Yes, I think Luca is as disturbing as you do.  It matters not - hand me the field sampling kit.  I will need to make some adjustments to it in order to survey for the proper base materials.\n\nYou have the kit, don't you?", completion = "Good - it pleases me to be working with someone who takes pride in not wasting my time.\n\nAfter I make some adjustments to this kit, you'll be ready to head out into the field.  You'll be using it to collect some vital data to the task at hand.\n\nIt will take just a moment for me to finish the modifications.  While you are waiting, you should probably start thinking about what you'd like to bring to the desert with you.\n\nYes, I said the desert.", objectives = "Bring the Field Sampling Kit to Apothecary Zinge in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[239] = { id = 239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westbrook Garrison Needs Help!", description = "The Garrison on our western border sends word of increasing gnoll and thief activity.  They're requesting we send more Stormwind soldiers... but we just don't have any to spare!\n\nIf you can help, we could use it.  Go and speak with Deputy Rainer at the Westbrook Garrison and see what he needs done.\n\nThe Garrison is down the road to the west.  After you cross the bridge over the small brook it will be to the right.", completion = "Marshall Dughan sent you, eh?  Well you're not from the army, but if Dughan sent you then that's good enough for me!\n\nOur situation is, to say the least, a stressed one.  I hope you can give us a hand.", objectives = "Go to the Westbrook Garrison and speak with Deputy Rainer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[240] = { id = 240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Jitters", description = "And here we are - \"Crab\" Cakes ala Grual!", progress = "{name}, you're here!  Do you have my food?!?", completion = "Aha!  Thank you, {name}.  Those really hit the spot!\n\nAnd here, please let me pay you for these!", objectives = "Return to Jitters with the Dusky Crab Cakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[243] = { id = 243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Field", description = "You will be headed to the Tanaris desert, testing the tissue consistency of the basilisks, scorpids, and hyena native there.  Obtain tissue samples and use them with the testing kit in tow; expect a chunk of the samples to fail.  I need eight acceptable samples of each creature type.\n\nIn addition, the goblins of Gadgetzan have a power source that must be used with this kind of modified kit.  Speak to Chief Engineer Bilgewhizzle and acquire one for the kit.\n\nReturn to me only when you are successful.", completion = "Ah, our model 4711-FTZ power sources!  We normally use them to power the water wells, but THANKS TO THE VILE NOMADS, we have an over abundance of power sources right now.\n\nSure, I can get you a power source for whatever nefarious science experiment you think you're trying to hide from me.  It ain't gonna be free though, {race}.  Nothing's free in Gadgetzan.", objectives = "Speak to Chief Engineer Bilgewhizzle in Gadgetzan about getting a power source for the testing kit.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[244] = { id = 244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Gnolls", description = "Hail, {class}.  I am charged to patrol this stretch of road.  Although the road is safe for now, I've seen gnoll encampments to the north and east of here.\n\nLakeshire must know of the gathering gnoll force!  Report to Deputy Feldon in Lakeshire and tell him of the gnolls.  Do this, and I'm sure Feldon will offer you a scout's wage.\n\nFeldon's usually inspecting the area south of the bridge to Lakeshire.", completion = "There are Redridge gnolls that close to Elwynn??  They may be poised to advance into our homeland.  Soon the people of Lakeshire may not be the only humans under siege!\n\nHere is your pay, though you bring us dire news.  And it comes at a bad time, for we are ill equipped to deal with it.", objectives = "Report to Deputy Feldon at the bridge south of Lakeshire in Redridge Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[245] = { id = 245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ight-Legged Menaces", description = "Hail, {class}. Perhaps you've seen those spiders that have taken over the western border? The eight-legged menaces are too much for us to handle, and the Commander hasn't enough manpower to spare so far from Darkshire.\n\nI hate to ask this of you, but you seem like you might be able to handle them. I can't promise you anything of great value, but I can reward you if you can help root out the filthy bugs.\n\nOh, and a word of advice, you'll want to avoid their venom if you can.", completion = "Ah! You're back. And not too much worse for wear, it'd seem. Of course, {name}, the Night Watch is grateful for your work, and I did promise you a reward, so here.", objectives = "Kill 15 Pygmy Venom Web Spiders, and then report back to Watcher Dodds in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[246] = { id = 246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assessing the Threat", description = "We don't have men to spare, but something must be done about those gnolls you reported to me.\n\nScout southern Redridge for gnolls.  Harry them, kill those you can and report back to me with a count of their numbers and an assessment of the threat they present.  You may find those gnolls camped all along the southern road of Redridge.\n\nDo this for the Stormwind Army, {name}, and you will be rewarded.", completion = "<Deputy Feldon listens to your report...>\n\nThere's a sizable force of gnolls encamped there, and from what you tell me they are tough ones.  It must not have been easy for you to gather this intelligence.\n\nHere you are, {name}.  We are grateful for your aid.\n\nAnd if you haven't already done so, speak with Marshal Marris and Magistrate Solomon within Lakeshire.  Our situation grows ever more desperate - those two will have need of you I'm sure.", objectives = "Kill 10 Redridge Mongrels and 6 Redridge Poachers, then report back to Deputy Feldon in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[247] = { id = 247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt Completed", objectives = "{name}, you have slain all three beasts that comprise the Ashenvale Hunt.  You have brought me adequate proof of their demise; there is no question of your strength and tenacity.  The blood of a hunter streaks through your veins, and you should be commended!\n\nPlease, accept this bauble as a sign of congratulations on your mighty deeds done in Ashenvale for the Horde today.  May your ancestors watch over you!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[248] = { id = 248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking Further", description = "I have been watching the Tower of Ilgalar, and can detect that Morganth is in conflict with the Orcs in Stonewatch Keep.  I do not know the reason behind their contention, but you may aid me in unraveling this mystery.\n\nTake another Glyph of Azora, then go to the top of the intact watch tower beside Stonewatch Keep.\n\nFind a suitable object on which to place the Glyph.  A chest or a jar -- some place where the glyph will not be noticed -- will suit my purpose.", progress = "This jar once held a foul-smelling liquor, but now lies empty and forgotten on a pair of barrels.", completion = "It is a suitable vessel for the Glyph of Azora, allowing Theocritus to delve into the minds within Stonewatch Keep.", objectives = "Climb the intact watch tower beside Stonewatch Keep in Redridge Mountains.\n\nFind a suitable container to place the Glyph of Azora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[249] = { id = 249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morganth", description = "After much observation, I have discovered Morganth's plans.\n\nHe searches for the Scythe of Elune...and he may have found it!  If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might.\n\nI am not prepared to pit myself against Morganth, but I fear he must be dealt with now.  So you must enter the Tower of Ilgalar and face Morganth.\n\nDefeat him, and bring me his Pendant of Shadow.  Do this, and the kingdom will owe you much.", objectives = "Defeat Morganth.\n\nBring his Pendant of Shadow to Theocritus at the Tower of Azora in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[250] = { id = 250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Threat Looms", description = "Thank the stars someone is concerned about the well-being of the Dam.  First the destruction of the Thandol Span and then the pillaging of Dun Modr!  I have no doubt that the Dam will be the target of the next Dark Iron threat.  Most of the security detail here was reassigned to the Alliance Front, including my top inspector.\n\nThat's why I need you, {name}.  I spotted some Dark Iron Sappers milling about the eastern ramp of the Dam.   Investigate the area and bring back a clue.", completion = "The suspicious looking barrel contains a strange smelling powder.", objectives = "Investigate the area near the eastern ramp of the Dam and bring Chief Engineer Hinderweir a clue that might reveal what the Dark Iron Dwarves are up to.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[251] = { id = 251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ranslate Abercrombie's Note", description = "Take the note you gave me to Sirra Von'Indi.  He's very learned in languages and ancient arts - if anyone here can translate this message, it's he.", progress = "A note from Abercrombie the hermit, eh?  I don't know him, though if he lives out at the graveyard then I do know his brains have rotted out!", completion = "<Sirra begins translating the note...>", objectives = "Bring the Letter to Ello to Sirra Von'Indi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[252] = { id = 252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Translation to Ello", description = "Oh my!  If what is written on this note is true, then Abercrombie's done something...unspeakable.\n\nYou better bring the translated note back to Ello.\n\nAnd do so quickly, for I fear a doom already lumbers toward our town...", progress = "Ah, is the note translated?  Please, let me see it...", completion = "<Ello reads the letter...and his face goes white.  He then looks at you...>\n\nAlthough the aid you gave Abercrombie may have been motivated from kindness, your actions have doomed our town.\n\n<Ello becomes lost in his thoughts...>", objectives = "Bring the Translated Letter to Lord Ello Ebonlocke", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[253] = { id = 253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ride of the Embalmer", description = "The Embalmer is a name told in one of our children's stories.  He was a kindly alchemist, driven mad by the death of his wife, Eliza.  To restore her, he used dark magic to place his own heart within the bosom of his dead spouse.\n\nThis revived Eliza...but it cursed her with a hunger for human flesh, forcing the Embalmer to keep her buried.\n\nHis heart is his power.  Find his wife's grave, retrieve his heart, and bring it to me while it still beats.  Do this and his power will be broken.", progress = "Have you yet found Eliza's grave?  Do you have the Embalmer's heart?", completion = "You've done it!  The magic within his heart will be proof against the Embalmer's evil, and a powerful aegis over the town of Darkshire.\n\nYou have done a great thing for our people, {name}.  Your name will remain in our annals forever.", objectives = "Find Eliza's grave. Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[254] = { id = 254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging Through the Dirt", objectives = "You dig through the semi-loose dirt over the grave...and find the remains of a coffin.\n\nWithin the coffin you can feel the vibrating scrapes of clawed fingers and the gnashing of rotted teeth...\n\nWill you open the coffin and retrieve the Embalmer's heart?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[255] = { id = 255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ercenaries", description = "Hunting wildlife gets old after a while. I'm into bigger game... much bigger actually. Ogres to be precise.\n\nThe dwarves here are quite concerned with the Mo'grosh Stronghold to the northeast, but they don't have the manpower to do much about it. If you'd like to join in on the hunt, please feel free to kill any ogres you find. Bring me news regarding the deed, and I'll split the reward from the arrangement I have with the Magistrate.", completion = "Ah, this is excellent news! Your efforts are greatly appreciated by myself and the people of Thelsamar. Better yet, if we can solve the ogre problem, we'll be able to shift our focus to those Light-burning troggs.", objectives = "Kelt Thomasin of the Mo'grosh camp has hired you to kill 4 Mo'grosh Ogres, 4 Mo'grosh Brutes and 4 Mo'grosh Enforcers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[256] = { id = 256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Chok'sul", description = "By order of the Magistrate of Thelsamar:\n\nChok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary.\n\nMonetary compensation will be provided when proof is brought to the Magistrate of Chok'sul's death.\n\nChok'sul was last seen at the ogre encampment in the northeastern part of Loch Modan.", progress = "Yes? Is there something I can do for you?", completion = "Yech! What is that thing? And why would you bring it...\n\nBloody--! Is it? Well, Light burn me, is that the head of that bloody ogre? This certainly is a catch then! Here, your reward and the thanks of myself and the people of Thelsamar.", objectives = "Kill Chok'sul and bring his head to Magistrate Bluntnose of Thelsamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[257] = { id = 257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Boast", description = "Think you can match wits with Daryl the Bold, huh? I should think not! Of course, you're more than welcome to try. Here's a challenge that should prove to be above your abilities, so don't feel too bad if you can't face up to it.\n\nA flock of buzzards has nested here in Loch Modan. Why don't you try to take down some of the beasts? Tell you what, if you meet my challenge, I'll give you my bow or gun.\n\n<He looks you over dismissively.>\n\nIt seems you haven't much to lose, anyways.", completion = "What? Success?\n\nTake it from me, Astridama, you don't let it get to your head. I mean, any unshaven boy with a bow could have killed such... small specimens. And I hope you don't enjoy killing the buzzards so much, yes? We wouldn't want them to become extinct. \n\nWell, err... Never let it be said that Daryl the Bold would not hold to his word.", objectives = "Kill 8 Mountain Buzzards and return to Daryl the Youngling in the Farstrider Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[258] = { id = 258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Challenge", description = "{name}ath, is it? I can tell you're bursting with pride over your hunting prowesst, hm? It's no large feat.\n\nYou should try your hand at boar hunting. Trust me, this is no Coldridge Valley boar hunt, so you'd best have a care with them.\n\nDon't feel bad if you fail. I'd give you the shirt off my back if you succeeded!\n\nHave I ever related to you the story of how I received my famous scar? No? It was two years ago...", completion = "You seem a bit worse for wear. No doubt the boars gave you some trouble, hm? No worries, I will be discreet about your struggle, I can imagine how hard it must be for you without the accusations of wagging tongues.\n\nOh! You managed to kill the boars? I... well, that is... that is to say, I'm not surprised! Any child could have--bet?\n\nWhat bet?", objectives = "Kill 10 Elder Mountain Boars and return to Daryl the Youngling in the Farstrider Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[261] = { id = 261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Scarlet Path", description = "I will be frank.  We are at war with the Scourge.  It is an evil that corrupts our people and infects our land.  It must be stopped before it overwhelms us and drags our world into shadow.  We of the Scarlet Crusade have sworn to fight the Scourge with body and soul.\n\nIf you are with us, then gather your courage and prove your allegiance--destroy the undead ravagers of Desolace, in the Valley of Bones to the south.\n\nDo this, and the Crusade will embrace you.", completion = "You have proven your resolve, and the Scarlet Crusade commends you.\n\nIf you do not shy from righteous slaughter, then perhaps your path lies with us...", objectives = "Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[262] = { id = 262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadowy Figure", description = "I must know who was that skulker in the shadows I saw the night my family was killed!\n\nPlease, {name}, you have shown your resourcefulness.  Please find that shadowy figure.  I must learn what secrets he holds!\n\nI do not have clues that you do not already know, but here - take the book you found at my farm.  Perhaps some of the townsfolk can link this book with its owner.", progress = "If you have something that belongs to the shadowy figure for whom you seek, then let me see it.  I may be able to divine something of its owner.", completion = "Hmm... Someone handled this book recently, someone who is driven by revenge.  But the impressions left on it, at least the impressions from the original owner, are faint.\n\nI can tell, however, that the original owner of this book is not a native of Darkshire.", objectives = "Take the book you found at Sven's farm and show it to townsfolk in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[263] = { id = 263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of the King's Lands", description = "The Mountaineers tell me you are quite brave and capable, {name}.  We need a {race} like you around here.  The Trogg problem isn't getting any better.  The reserves have been called to the front and we're all alone out here.  But now that we have a seasoned {class} here, let's see what you can do.\n\nGo out and kill 8 Stonesplinter Shaman and 8 Stonesplinter Bonesnappers. You should find them in and around the caves in the southern mountains.\n\nLet's see if you live up to your reputation, Trogg-Slayer.", completion = "I knew the second I laid eyes on you, {name}, that you would make Ironforge proud.  You have served King Magni well.  Now that you've proven yourself to be such a loyal aid to the Kingdom, perhaps you should talk with the Captain to see if he'll entrust you with a higher detail.\n\nI salute you, {name}.", objectives = "Mountaineer Wallbang in the southern guard tower wants you to kill 8 Stonesplinter Shaman and 8 Stonesplinter Bonesnappers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
